  ('fraprotocolRelSet', 'fra', 'protocolRelSet', 'Ensemble de relations de protocole', 'Ensemble de catégories pour les valeurs valides de relationshipID dans la table protocolRelationships.', 'À n''utiliser que pour la relation ID de la table protocolRelationships table relationshipID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraprotocols', 'fra', 'protocols', 'Table de protocoles', 'La table qui contient les protocoles.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('fraprotocolsOrder', 'fra', 'protocolsOrder', 'L’ordre des colonnes de la table de protocoles', 'Indique l’ordre des colonnes dans la table de protocoles.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
