  ('engdatasets', 'eng', 'datasets', 'Dataset table', 'A report table for capturing details about data''s parental data set and data custodians. Supplying attribution for data collectors.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engdatasetsOrder', 'eng', 'datasetsOrder', 'Datasets table column order', 'Specifies the order of the columns in a Datasets table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engdatasetsRequired', 'eng', 'datasetsRequired', 'Dataset table required headers', 'Specifies the columns required in a Datasets table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engdataTypes', 'eng', 'dataTypes', 'Data types', 'The data type for a part.', 'Data types used in the ODM include: varchar, booleen, float, category, date, time, datetime, url, email. dataType corresponds the the entry or cell within a data table, most commonly within a report table. If the data entry has a unit, then the dataType corresponds to the unit and the dataType refers to ''unit''. If the data entry is a category, then the dataType refers to ''category''. All categories are varchar. Otherwise the dataType is identifed within the part entry. TBA: dataType for dictionary.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engdate', 'eng', 'date', 'Date data type', 'The data type for date data (does not include time).', 'Only used for the dictionary entries of parts.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engdateDep', 'eng', 'dateDep', 'Date', 'Date', 'date on which the assayMethod was created or updated (for version update).', '1.0.0', '3.0.0', 'Still depreciated, but partID updated to reflect that while avoiding colisions with the new date data type.', NULL),
