  ('enggPergTS', 'eng', 'gPergTS', 'Grams per total solids', 'Grams per total solids (g/gTS)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggpl20', 'eng', 'gpl20', 'GNU General Public License v2.0', 'The licensing for the measure or data set is managed under the GNU General Public License v2.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enggpl30', 'eng', 'gpl30', 'GNU General Public License v3.0', 'The licensing for the measure or data set is managed under the GNU General Public License v3.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enggPO43gTS', 'eng', 'gPO43gTS', 'Orthophosphate per total solids', 'orthophosphate per total solids (gPO43–/gTS)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggPO4PgTS', 'eng', 'gPO4PgTS', 'Orthophosphate as phosphorus per total solids', 'orthophosphate as phosphorus per total solids (gPO4-P/gTS)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggrabInst', 'eng', 'grabInst', 'Grab samplers', 'Grab sampler instruments; manually collect a single sample at a point in time.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggrams', 'eng', 'grams', 'Grams', 'A unit of mass or weight.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggramSt', 'eng', 'gramSt', 'Gram stain', 'After the sample is taken, the Gram stain is colored purple. Then, a solvent is added to the stain. When the solvent combines with bacteria in a sample, the bacteria will either stay purple or turn pink or red. If the bacteria remain purple, they are Gram-positive. If the bacteria turn pink or red, they are Gram-negative.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggraphmap', 'eng', 'graphmap', 'GraphMap', 'GraphMap. A long-read specific mapper. Long-read aligner optimized for highly error-prone reads. Best for: De novo assemblies using long-read data.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggraSet', 'eng', 'graSet', 'Gravity settling', 'Describes solid separation from a wastewater sample where the sample material is allowed to settle by gravity, and then separated.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggrb', 'eng', 'grb', 'Grab sample', 'A single large representative grab sample.', 'If the sample was collected over a series of hours or is a composite sammple, please use partID = comp', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('enggritCham', 'eng', 'gritCham', 'Grit chamber ', 'A sedimentation basin in wastewater treatment that removes heavy, inorganic particles (e.g., sand, gravel) before biological treatment.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggromstole', 'eng', 'gromstole', 'Gromstole 1.0 Script', 'Gromstole 1.0 Script for sequencing.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggroup', 'eng', 'group', 'Group', 'Unique identifier for a group of measures. Mostly applicable for measures, methods, units, and aggregations.', 'A collection of related measures. For example, SARS-CoV-2 is a group. Within the SARS-CoV-2 group, there are measure classes tht include RNA alleles (N1, N2, E, etc.), mutations, (E484K0), an entire sequence, viral proteins, etc. Currently groups are used for measures only.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggroups', 'eng', 'groups', 'Groups', 'A collection of related measures.', 'Used primary to group measurements and methods, this helps pare down the drop down list for a given measurement or ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enggrowBroth', 'eng', 'growBroth', 'Growth in enrichment broth', 'The selective cultivation of microorganisms in a nutrient-rich liquid medium to increase their concentration before analysis.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggrWa', 'eng', 'grWa', 'Ground water', 'Underground water which is located in pore spaces found in rock or unconsolidated deposits such as soil, clay, or gravel.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggsa', 'eng', 'gsa', 'Genome Sequence Archive (GSA)', 'Genome Sequence Archive (GSA).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggsnap', 'eng', 'gsnap', 'GSNAP', 'GSNAP. A specialized read mapper. A splice-aware aligner for RNA-seq reads.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggt', 'eng', 'gt', 'Guanidine Thiocyanate', 'A buffer solution/medium that serves as a strong preservative for viral RNA, commonly used in molecular biology for RNA preservation.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggte', 'eng', 'gte', 'Genomic Target Enrichment', 'The molecular technique used to selectively capture and amplify specific regions of interest from a genome.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enggteSet', 'eng', 'gteSet', 'Genomic Target Enrichment Methods Set', 'The set for valid inputs for the Genomic Target Enrichment method.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engh5n1', 'eng', 'h5n1', 'H5N1 avian influenza A virus (IAV)', 'General measurement for the Highly Pathogenic Avian Influenza Virus (HPAIV), the H5N1 Influenza A Virus (IAV) subtype.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enghaemophilusGrp', 'eng', 'haemophilusGrp', 'Haemophilus Group', 'A group of measures/methods related to haemophilus bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enghAg', 'eng', 'hAg', 'See Header for Aggregation', 'An indicator to show in a wide-name that aggregation information is located in a different column.', 'Not a valid value for aggregation in the standard long-format.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enghandHygAdv', 'eng', 'handHygAdv', 'Hand hygiene advisory', 'Public guidance promoting handwashing or sanitizing to reduce infection risk.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enghbss', 'eng', 'hbss', 'Hank''s Balanced Salt Solution (HBSS)', 'Hank''s Balanced Salt Solution (HBSS) - Nutrient-rich buffer that maintains cell and microbial integrity in samples.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enghcAct', 'eng', 'hcAct', 'Healthcare activity', 'Healthcare activity occurred upstream of the sampling site.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enghcf', 'eng', 'hcf', 'Healthcare facility', 'A building for the provision of healthcare, not otherwise specified.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('enghCo', 'eng', 'hCo', 'See Header for Compartment ', 'A indicator for wide-names that the compartment information is stored in a separate column.', 'Not a valid value for compartment in the standard long-format.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('enghDucreyi', 'eng', 'hDucreyi', 'Haemophilus ducreyi', 'Haemophilus ducreyi', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engheader', 'eng', 'header', 'Header', 'Header for a table. Also known as a table variable or entiy relationship ''attribute''. ', 'Header is the top row or the variable name in a table.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enghealthAdm', 'eng', 'healthAdm', 'Health administration or planning agency', 'Health adminstrative or planning organization. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('enghealthRegion', 'eng', 'healthRegion', 'Health Region for a Site', 'A free-text variable for listing the health region for a given site.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engheatInacSARS', 'eng', 'heatInacSARS', 'Heat inactivated sars-cov-2 virus spike target', 'Heat inactivated SARS-CoV-2 virus is used as the recovery efficiency control target.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
