  ('englog10gcngDNA', 'eng', 'log10gcngDNA', 'Log10 gene copies per nanogram total DNA', 'log10 gene copies per nanogram total DNA', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('englog10ugG', 'eng', 'log10ugG', 'log10 micrograms per g', 'Unit for log10 micrograms per gram', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('englog10ugL', 'eng', 'log10ugL', 'log10 micrograms per L', 'Unit for log10 micrograms per litre', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('englogAggrSet', 'eng', 'logAggrSet', 'Logarithmic scale aggregation set', 'The aggregation set that contains all aggregations that exist on the logarithmic scale (rather than linear or qualitative).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('englongSurv', 'eng', 'longSurv', 'Longitudinal, repeat sampling surveillance program', 'A surveillance strategy in which an individual or site is selected to undergo repeat sampling over a defined period of time.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('englookup', 'eng', 'lookup', 'Dictionary tables', 'Tables to describe and support the ODM dictionary. ', 'These tables hold information on sets, all parts, and support multiple languages and translations. The tables are updated by the ODM development team when a new ODM version is created.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engloq', 'eng', 'loq', 'Limit of quantification (LOQ)', 'Sample limit of quantification (LOQ) is defined as “the concentration of a target that can be quantified with an acceptable level of precision when present in a sample” (Ahmed et al., 2021).', 'Limit of quantification (LOQ) for this method if one exists.', '1.1.0', '3.0.0', 'changed quality indicator set from general to measure.', NULL),
  ('englow', 'eng', 'low', 'Low severity', 'A marker for low severity', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('englowCovMut', 'eng', 'lowCovMut', 'Low Coverage of Characteristic Mutations', 'Low coverage of characteristic mutations.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('englowerCI95', 'eng', 'lowerCI95', 'Lower limit of a 95% confidence interval', 'Specifies the the lower limit of a 95% confidence interval.', 'Should typically be linked to an upper limit, and some indication of data spread (ie. standard deviation), and a mean/median measure.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('englowQualSeq', 'eng', 'lowQualSeq', 'Low-quality Sequence', 'Low-quality sequence.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('englowSNRatio', 'eng', 'lowSNRatio', 'Low Signal-to-Noise Ratio', 'Low signal-to-noise ratio.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('englowVol', 'eng', 'lowVol', 'Low-volume sample', 'Sample is low-volume, but was run regardless. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('englp81V', 'eng', 'lp81V', 'LP.8.1 Variant', 'The LP.8.1 variant of SARS-CoV-2, a Omicron subvariant of JN.1, and FLiRT variant.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('englPGC', 'eng', 'lPGC', 'Low Percent of Genome Captured', 'Only captured a small/low percentage of the genome. ', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('englppa24s', 'eng', 'lppa24s', 'Omicron Variant LPPA24S mutation', 'Omicron Variant LPPA24S mutation', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('englppl13c', 'eng', 'lppl13c', 'LaTeX Project Public License v1.3c', 'The licensing for the measure or data set is managed under the LaTeX Project Public License v1.3c.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('englrs', 'eng', 'lrs', 'Lactated Ringer’s Solution', 'A buffer solution/medium sometimes used in combination with other preservatives to stabilize microbial samples.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('englsec', 'eng', 'lsec', 'Liter per second', 'liter per second (L/s)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engltcf', 'eng', 'ltcf', 'Long-term care facility', 'A residential healthcare facility that provides 24-medical care. These are also called skilled nursing facilities.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engltcfAl', 'eng', 'ltcfAl', 'Long-term care - assisted living or retirement home', 'A residential facility that provides assistance with daily care but generally does not provide skilled nursing care. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engltcfO', 'eng', 'ltcfO', 'Other long-term care', 'Other residential facilities that provide daily and/or medical care, but are not defined as nursing home/skilled nursing facilities or assisted living facilities. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engltDpcr', 'eng', 'ltDpcr', 'Life technologies digital PCR', 'Describes a PCR analysis done using Life Technologies'' digital PCR technology.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engluminWWExtract', 'eng', 'luminWWExtract', 'luminultra wastewater extraction kit', 'luminultra wastewater extraction kit', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
