  ('engm3H', 'eng', 'm3H', 'Cubic metres per hour', 'Cubic metres per hour.', 'NA', '1.1.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engm3min', 'eng', 'm3min', 'Cubic meter per minute', 'cubic meter per minute (m^3/min)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engm3S', 'eng', 'm3S', 'Cubic metres per second', 'Cubic metre per second.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engmafft', 'eng', 'mafft', 'MAFFT', 'Sequencing software that performs multiple sequence alignment, commonly used in consensus sequence generation.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmagBead', 'eng', 'magBead', 'Magnetic nanobead binding', 'The use of tiny, magnetized beads to selectively capture and isolate biological molecules (e.g., DNA, proteins) in a magnetic field.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmagInst', 'eng', 'magInst', 'Magnetic separation racks', 'Magnetic separation rack instrument; may be used with magnetic beads for nucleic acid extraction.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmalariaGrp', 'eng', 'malariaGrp', 'Plasmodium or Malaria Group', 'A group of measures/methods related to plasmodium parasites or malaria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engmall', 'eng', 'mall', 'Shopping mall ', 'A large commercial complex with multiple retail stores, services, and restaurants.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmanComp', 'eng', 'manComp', 'Manual Composite Sample', 'Specifies a composite sample where the sub-samples were collected manually.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engmanufacturer', 'eng', 'manufacturer', 'Manufacturer', 'Manufacturer of an instrument.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engmapSplice', 'eng', 'mapSplice', 'MapSplice', 'MapSplice. A specialized read mapper. Designed specifically for spliced alignment of RNA-seq reads. Best for: Transcriptomics with a focus on detecting splice junctions.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmash', 'eng', 'mash', 'mash Software', 'A lineage or clade analysis software tool for the clustering-based method of lineage and clade analysis, comparing large genomes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmaskMand', 'eng', 'maskMand', 'Mask mandate', 'A legal requirement for individuals to wear masks in specified settings.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmaskRec', 'eng', 'maskRec', 'Mask recommendation', 'Guidance encouraging the public to wear masks to reduce disease transmission.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmasurca', 'eng', 'masurca', 'Maryland Super Read Celera Assembler (MaSuRCA)', 'A sequencing software that is a hybrid assembler that can integrate both short and long reads for high-quality assemblies, and large, complex genomes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmatChar', 'eng', 'matChar', 'Sample Material Characteristics', 'A site measurement for describing the qualitative characteristics of the sample material in situ (ie. The material from which the sample is collected.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engmatCharSet', 'eng', 'matCharSet', 'Sample Material Characteristics Set', 'The set for recording the possible valid values for describing the sample material characteristics.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
