  ('engmeasureSets', 'eng', 'measureSets', 'Measure set report table', 'The table that identifies sets of measures.', 'Examples of measure sets include a set of replicates, dilutions (used to generate a Ct curve) or varients that are identified in a single sample.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engmeasureSetsOrder', 'eng', 'measureSetsOrder', 'Measure sets table column order', 'Specifies the order of the columns in a Measure Sets table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
