  ('engparent', 'eng', 'parent', 'Parent sample ID', 'If this sample has been pooled into one big sample for analysis this indicates the sample of the larger pooled sample.', 'NA', '1.1.0', '2.0.0', 'Replaced in V2 with approach to describe sample relationships that allows greater flexibility than soley parents.', NULL),
  ('engparSiteID', 'eng', 'parSiteID', 'Parent Site ID', 'The siteID that is a parent to another siteID; usually the sub-site will be contained in the parentSite.', 'An example would be surface testing in a LTC facility. The LTC facility would be the parentSiteID, and the various rooms/surfaces would be the sub-sites, or child-sites.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartDesc', 'eng', 'partDesc', 'Part description', 'The description of the part.', 'Provides description of the part, used for tranlsation.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartID', 'eng', 'partID', 'eng_label', 'eng_descr', 'eng_instr', '1.0.0', '2.0.0', 'NA', NULL),
  ('engpartInstr', 'eng', 'partInstr', 'Part instruction', 'Additional notes and instructions on how a part is used and/or defined.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engparts', 'eng', 'parts', 'Parts Look-up table', 'Look up table containing all parts in of the data model.', 'Contains all parts, including self-referential parts.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartsOrder', 'eng', 'partsOrder', 'Parts table column order', 'Order of headers in the Parts table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartsRequired', 'eng', 'partsRequired', 'Parts table required headers', 'Required headers in the Parts table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartSupport', 'eng', 'partSupport', 'Part Support', 'Parts designed to support the metadata definition of other parts in the parts table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartType', 'eng', 'partType', 'Part types', 'Part types describe the purpose or use of the part. ', 'Enivornment data has three main part types: measure (i.e. covN1 viral measures, wasteawater flow rate, temperature), method (e.g. how the measure was taken), and attribute (such as a site name). See description of each of the part types within categorySetID = partTypeCatSets.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpartTypeInput', 'eng', 'partTypeInput', 'Part type input (wide table)', 'The partID for the part type being used in a wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpartTypeName', 'eng', 'partTypeName', 'Part type name (wide table)', 'The part type being used in a wide name.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpassiveGen', 'eng', 'passiveGen', 'Passive Sample - General', 'Used to specify a passive sampling method not otherwise specified was used to collect the sample.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpasteur', 'eng', 'pasteur', 'Pasteurized sample', 'Binary indicator for whether a sample was pasteurized as part of its processing.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpathogenwatch', 'eng', 'pathogenwatch', 'Pathogenwatch', 'Pathogenwatch. Focus: Integrates MLST, serotyping, and resistance typing with a user-friendly interface. Applications: Primarily used for Salmonella and Escherichia coli. Features: Combines typing results with interactive visualization.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpatricRast', 'eng', 'patricRast', 'PATRIC/RAST Database', 'Database that hosts resistance gene annotations within their microbial genome data resources.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpbfinder', 'eng', 'pbfinder', 'PBPfinder', 'PBPfinder. Used for typing and serotyping of Streptococcus pneumoniae through analysis of penicillin-binding proteins and capsular genes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpbs', 'eng', 'pbs', 'Phosphate Buffered Saline (PBS)', 'An isotonic solution for general sample preservation, used when immediate freezing is available.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpceDep', 'eng', 'pceDep', 'Primary Clarifier Effluent depreciated', 'Effluent obtained after primary clarifiers.', 'Deprecated in version 2, please do not use. Duplicate of the sampleMat categories - refer to those.', '1.0.0', '2.0.0', 'depreciated, site material like this is now captured in the sample table', NULL),
  ('engpCode', 'eng', 'pCode', 'Postal or Zip Code', 'The zip code or postal code for a given address, specifying a specifc geographic area.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpcr', 'eng', 'pcr', 'qPCR Class', 'Measures and methods relating to qPCR.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpcrAct', 'eng', 'pcrAct', 'PCR Action/Activity', 'Describes a given PCR cycle for delineating more method information.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpcrActSet', 'eng', 'pcrActSet', 'PCR action/activity set', 'The set capturing containing all of the valid methods for the PCR activity cycles.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpcrCycles', 'eng', 'pcrCycles', 'PCR Quanitification Cycles', 'A count unit of how many Polymerase Chain Reaction (PCR) cycles it took to detect a real signal from a sample. Equivalent to the PCR cycle number at which a sample''s reaction curve intersects the threshold line.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpcrmeth', 'eng', 'pcrmeth', 'PCR method', 'Description of the PCR method.', 'Description of the PCR method used', '1.0.0', '2.0.0', 'description wording', NULL),
  ('engpcrQualitySet', 'eng', 'pcrQualitySet', 'PCR quality set', 'Quality set for PCR measures.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpcrSeq', 'eng', 'pcrSeq', 'PCR Sequencing Selection Method', 'Specifies the PCR selection method for sequencing, ie. that a pre-determined primer was used.', 'Primer should be specified if this is selected.', '2.0.0', '3.0.0', 'corrected part type to be categories rather than methods', NULL),
  ('engpcrSet', 'eng', 'pcrSet', 'PCR Method set', 'The set capturing containing all of the valid methods for the PCR method.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpcs', 'eng', 'pcs', 'Primary Clarifier Sludge depreciated', 'Sludge produced by primary clarifiers.', 'NA', '1.0.0', '2.0.0', 'depreciated, site material like this is now captured in the sample table', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('engpeeps', 'eng', 'peeps', 'Number of people', 'Unit specifying a number of people.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpEfflu', 'eng', 'pEfflu', 'Primary clarifier effluent', 'Effluent obtained after primary clarifiers', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engpeg', 'eng', 'peg', 'Polyethyleneglycol (PEG) precipitation', 'Peg precipitation', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('engpehaplo', 'eng', 'pehaplo', 'PEHaplo', 'A sequencing software that is an assembler that considers heterozygosity in diploid genomes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engperc', 'eng', 'perc', 'Percent', 'Percentage.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpercContam', 'eng', 'percContam', 'percent read contamination ', 'The percent of the total number of reads identified as contamination (not belonging to the target organism) in a sequence dataset.', 'Provide the percent contamination value (no need to include units).', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpercentUnitSet', 'eng', 'percentUnitSet', 'Percent unit set', 'Unit set for percentages.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpercNLength', 'eng', 'percNLength', 'percent Ns across total genome length', 'The percentage of the assembly that consists of ambiguous bases (Ns).', 'Provide a numerical value (no need to include units).', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpercRec', 'eng', 'percRec', 'Percent recovery', 'Percent of the surrogate recovery for a recovery efficiency control assay (as a unit).', 'Use this for reporting the results of any recovery control assay.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engpersonPerKm', 'eng', 'personPerKm', 'Persons for square kilometre', 'Persons per square kilometre.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpersonPerMile', 'eng', 'personPerMile', 'Persons per square mile', 'Persons per square mile.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpgap', 'eng', 'pgap', 'PGAP (Prokaryotic Genome Annotation Pipeline)', 'PGAP (Prokaryotic Genome Annotation Pipeline). Focus: Annotation pipeline that integrates MLST and antigen typing. Applications: Broad bacterial pathogens. Features: Provided by NCBI, designed for high-throughput workflows.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engph', 'eng', 'ph', 'pH', 'pH measurement', 'NA', '1.1.0', '2.0.0', 'description wording, structure', NULL),
  ('engpha', 'eng', 'pha', 'Public Health Actions Report Table Shortname', 'The abbreviated short name used to reference the table for recording information on public health actions.', 'table', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpha4geForm', 'eng', 'pha4geForm', 'PHA4GE Format', 'Dataset was originally recorded and/or stored in PHA4GE format.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphac', 'eng', 'phac', 'Access to phac', 'If this is ''no'', the data will not be available to employees of the Public Health Agency of Canada - PHAC. If missing, data will be available to employees of the Public Health Agency of Canada - PHAC.', 'NA', '1.0.0', '2.0.0', 'depreciated, sharing moved to sharing schema', NULL),
  ('engphActionID', 'eng', 'phActionID', 'Public Health Action ID', 'Unique identifier for public health actions.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphActions', 'eng', 'phActions', 'Public Health Actions Report Table', 'Table for recording information on public health actions.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphActionsOrder', 'eng', 'phActionsOrder', 'Public health actions table column order', 'Specifies the order of the columns in the public health actions table.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphActionsRequired', 'eng', 'phActionsRequired', 'Public health actions table required headers', 'Required headers in the public health actions table.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphAdvise', 'eng', 'phAdvise', 'Public health advisory', 'A public health action type wherein a public health advisory is deseminated to the public.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphAdviseSet', 'eng', 'phAdviseSet', 'Public Health Advisory Value Set', 'A set of valid categories for the public health action field, where the action type is ''publi health advisory''.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphage', 'eng', 'phage', 'PHAGE', 'PHAGE header', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphageGrp', 'eng', 'phageGrp', 'Bacteriophage Group', 'A group of measures/methods related to bacteriophages.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engphageNotes', 'eng', 'phageNotes', 'PHAGE - notes', 'PHAGE notes', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphagetype', 'eng', 'phagetype', 'Phagetyping Results', 'The phagetyping results from an organism.', 'Please record in numerical code for the profile. ie. convert lysis profiles into numerical codes for easier classification. For instance: binary presence/absence profile (e.g., 11001 for five phages) is converted into a unique numerical identifier for the phage type.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphandango', 'eng', 'phandango', 'Phandango', 'Phandango. A visualization tool that integrates serotype predictions with phylogenetic analyses for population studies. Often used alongside other serotyping tools.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpharmPl', 'eng', 'pharmPl', 'Pharmaceutical manufacturing plant', 'An industrial building in which pharamceutical drugs are synthesised and processed on an industrial scale.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpHClass', 'eng', 'pHClass', 'pH class', 'Measures and methods relating to pH.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphEmerg', 'eng', 'phEmerg', 'Public health emergency (outbreak)', 'Indicates a public health emergency from an outbreak.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphenCl', 'eng', 'phenCl', 'Phenol chloroform', 'Nucleic acid extraction performed using phenol chloroform.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('engphesODMFormV1', 'eng', 'phesODMFormV1', 'PHES-ODM Version 1 Format', 'Dataset was originally recorded and/or stored in PHES-ODM version 1 format.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphesODMFormV2', 'eng', 'phesODMFormV2', 'PHES-ODM Version 2 Format', 'Dataset was originally recorded and/or stored in PHES-ODM version 2 format.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphesODMFormV3', 'eng', 'phesODMFormV3', 'PHES-ODM Version 3 Format', 'Dataset was originally recorded and/or stored in PHES-ODM version 3 format.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphi6', 'eng', 'phi6', 'Pseudomonas virus phi6', 'Measure of the amount of pseudomonas virus phi6.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphi6Mat', 'eng', 'phi6Mat', 'phi6 spike target', 'Pseudomonas virus phi6is used as the recovery efficiency control target.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphone', 'eng', 'phone', 'Country national phone prefix', 'International dialing code for the country.', 'Preprogrammed into dictionary tables, not editable by users.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engphos', 'eng', 'phos', 'Total phosphorous', 'Total phosphorous', 'NA', '1.1.0', '2.0.0', 'description wording, structure', NULL),
  ('engphostot', 'eng', 'phostot', 'Total Phosphates', 'Total phosphates', 'NA', '1.1.0', '2.0.0', 'description wording, structure', NULL),
  ('engphred', 'eng', 'phred', 'PHRED quality score', 'PHRED Quality Score For Sequencing', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphy', 'eng', 'phy', 'Physical property', 'A physical property or object not characterized by life or chemistry.	', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engphyloPhIAn', 'eng', 'phyloPhIAn', 'PhyloPhlAn Software', 'A lineage or clade analysis software tool, specialized in high-resolution phylogenetic analysis, typically used for microbial clade analysis.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphyloSuite', 'eng', 'phyloSuite', 'PhyloSuite Software', 'An integrated platform for sequence alignment, phylogenetic reconstruction, and clade assignment.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphyML', 'eng', 'phyML', 'PhyML Software', 'A lineage or clade analysis software tool that builds phylogenetic trees using maximum likelihood methods, with clade confidence assessments.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engphysical', 'eng', 'physical', 'Physical class', 'Measures and methods related to generic physical properties.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpicard', 'eng', 'picard', 'Picard MarkDuplicates', 'A deduplication method within the Picard suite that marks duplicate reads in BAM files based on mapped location.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpipelineID', 'eng', 'pipelineID', 'Pipeline ID', 'A primary key linked to a single measure (may be used multiple times), it is the shorthand for the data transformation pipeline used. Serves as a data pipeline identifier.', 'Can be used to link multiple data treatments together - rows of differe related treatments will share the same pipelineID.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpiqmie', 'eng', 'piqmie', 'PIQMIe', 'A comprehensive QC and contamination assessment pipeline for metagenomic datasets and sequencing data.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpiSeqQC', 'eng', 'piSeqQC', 'PiSeqQC', 'A QC pipeline tool for sequencing data for microbiome and metagenomic sequencing data, including quality filtering and contaminant removal.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpK', 'eng', 'pK', 'Primary key', 'Primary key for a table. ', 'All report tables have a primary key. Each row in a report table has unique identifier recorded in the primary key. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engplasmodium', 'eng', 'plasmodium', 'Plasmodium', 'Plasmodium', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engplatanus', 'eng', 'platanus', 'Platanus', 'A sequencing software that is an assembler, optimized for large, diploid genome assemblies, particularly plants.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpluDra', 'eng', 'pluDra', 'Plumbing drain', 'An artificial channel which transports unwanted water or waste liquids away from their source, either to a more useful area, a receptacle, or into sewers or stormwater mains as waste discharge to be released or processed.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpmFloMean', 'eng', 'pmFloMean', 'PMMoV- and flow-normalized mean', 'Mean measure normalized to amount of PMMoV and wastewater flow.', 'Mostly used for reporting specific alleles (N1, N2, E, etc.)', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpmmovGrp', 'eng', 'pmmovGrp', 'PMMoV Group', 'A group of measures/methods related to the Pepper Mild Mottle Virus (PMMoV).', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpmmovNorm', 'eng', 'pmmovNorm', 'PMMoV-normalized mean', 'Mean measure normalized to amount of PMMoV.', 'Mostly used for reporting specific alleles (N1, N2, E, etc.)', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpmmovStand', 'eng', 'pmmovStand', 'PMMoV Standarized', 'This data treatment standardizes the measurement value to concentration levels of pepper mild mottle virus (PMMoV).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpmmvABIFor', 'eng', 'pmmvABIFor', 'PMMV forward primer (ABI)', 'PMMV forward primer (ABI)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpmmvABIProbe', 'eng', 'pmmvABIProbe', 'PMMV probe (ABI)', 'PMMV probe (ABI)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpmmvABIRev', 'eng', 'pmmvABIRev', 'PMMV reverse primer (ABI)', 'PMMV reverse primer (ABI)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpo', 'eng', 'po', 'Polygon table Shorthand', 'The abbreviated short name used to reference the The table that contains information about the geometry of a geographic area.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engpogr', 'eng', 'pogr', 'Post-Grit depreciated', 'Raw wastewater after a treatment plant''s headworks.', 'NA', '1.0.0', '2.0.0', 'depreciated, site material like this is now captured in the sample table', NULL),
  ('engpoLic', 'eng', 'poLic', 'Polygon License', 'The license for the availability of the polygon shapefile.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolicy', 'eng', 'policy', 'Policy and political sector or organization', 'Describes organizations whose core focus is on policy or political activity.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpolioGrp', 'eng', 'polioGrp', 'Poliovirus Group', 'A group of measures/methods related to polioviruses.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engpoly', 'eng', 'poly', 'Polygon', 'A measure made on a compartment or property within a polygon.', 'An example would be the population of a polygon; this specimen is used for measures at the polygon level, where site or population might not be entirely appropriate.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolygonID', 'eng', 'polygonID', 'Polygon ID', 'Unique identifier for the polygon.', 'A polygon is a geographic are representing the capment area of an environmental sample.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engpolygonIDObject', 'eng', 'polygonIDObject', 'Polygon ID Object', 'The polygon ID Object in a polygon relationship.', 'The polygon relationship should be read as "''subject'' is ''relationshipID'' to ''object''".', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolygonIDSubject', 'eng', 'polygonIDSubject', 'Polgygon ID Subject', 'The polygon ID subject in a polygon relationship.', 'The polygon relationship should be read as "''subject'' is ''relationshipID'' to ''object''".', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolygonRelationships', 'eng', 'polygonRelationships', 'Polygon Relationships Table', 'Table for recording the relationships between polygons.', 'NA', '2.3.0', '2.3.0', 'added in V2.3.0', NULL),
  ('engpolygonRelationshipsOrder', 'eng', 'polygonRelationshipsOrder', 'Polygon relationships table column order', 'Specifies the order of the columns in the polygon relationships table.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolygonRelationshipsRequired', 'eng', 'polygonRelationshipsRequired', 'Polygon relationships table required headers ', 'Required headers in the polygon relationships table.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolygonRelID', 'eng', 'polygonRelID', 'Polygon relationship ID', 'Unique identifier for each row in the polygon relationships table.', 'Provisional PK.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolygons', 'eng', 'polygons', 'Polygon table', 'The table that contains information about the geometry of a geographic area.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engpolygonsOrder', 'eng', 'polygonsOrder', 'Polygons table column order', 'Specifies the order of the columns in a Polygons table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpolygonsRequired', 'eng', 'polygonsRequired', 'Polygon table required headers', 'Specifies the columns required in a Polygons table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpolyPop', 'eng', 'polyPop', 'Polygon Population', 'An attribute of a polygon, which specifies the population of that polygon. A rough estimate of the number of human residents.', 'NA', '2.0.0', '2.3.0', 'Updated to a measurement after being removed as a header in the polygons table.', NULL),
  ('engpolySiSpecimenSet', 'eng', 'polySiSpecimenSet', 'Polygon or site specimen set', 'A specimen set that inculdes polygon or site specimen.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpolySpecimenSet', 'eng', 'polySpecimenSet', 'Polygon specimen set', 'A specimen set that inculdes only a polygon specimen.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engpooled', 'eng', 'pooled', 'Pooled', 'Is this a pooled sample, and therefore composed of multiple child samples obtained at different sites', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engpop', 'eng', 'pop', 'Population', 'An measure or observation for a geographic area or population. ', 'Examples include human compartment measures such as case numbers, hospitalization rates for diseases or surface or air compartment measures such as snow coverage or ambient temperature.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
