  ('engqiampDSP', 'eng', 'qiampDSP', 'qiagen qiaamp dsp viral rna mini kit', 'qiagen qiaamp dsp viral rna mini kit', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engqiaSeqFX', 'eng', 'qiaSeqFX', 'QIAseq FX DNA Library Kit', 'QIAseq FX DNA Library Kit by Qiagen. Alibrary prep kit that uses enzymatic fragmentation, suitable for a variety of applications, including whole-genome sequencing.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engqpcr', 'eng', 'qpcr', 'Quantitative Real-Time PCR', 'Real-time PCR, also called ''quantAggScale'' PCR', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqPCRinst', 'eng', 'qPCRinst', 'qPCR instruments (quantitative PCR)', 'A quantitative PCR instrument, to detect and quantify specific DNA/RNA targets.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engqProfiler2', 'eng', 'qProfiler2', 'qProfiler2', 'A QC pipeline tool for sequencing data that produces reports with detailed QC metrics for aligned and unaligned reads.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engqr', 'eng', 'qr', 'Quality reports table Shorthand', 'The abbreviated short name used to reference the The table for recording the various quality metrics and indicators for samples and measures.', 'table', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('engqualAggScale', 'eng', 'qualAggScale', 'Qualitative', 'The qualitative aggregation scale.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityControl', 'eng', 'qualityControl', 'Quality control', 'A measure or sample taken for the purpose of quality control.', 'Measures with this category are take to assess quality control.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityFlag', 'eng', 'qualityFlag', 'Quality flag', 'A field for reporting any quality concerns - of lack thereof - for a sample or measure.', 'Types of quality flag vary on context; please see the qulaityFlagSet to be confirm.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityIndicators', 'eng', 'qualityIndicators', 'Quality indicators', 'A measure of the quality of a reported value or sample.', 'Only used for the dictionary entries of parts.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityIndSet', 'eng', 'qualityIndSet', 'Quality Indicator Set Header', 'The quality set that corresponds to a given part. Only applicable for samples and measures.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityIndSets', 'eng', 'qualityIndSets', 'Quality indicator sets', 'Sets of quality indicators or measures. For example, PCR have a quality measure set.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityReportID', 'eng', 'qualityReportID', 'Quality report ID', 'A unique identifier for a given quality report.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityReports', 'eng', 'qualityReports', 'Quality reports table', 'The table for recording the various quality metrics and indicators for samples and measures.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityReportsOrder', 'eng', 'qualityReportsOrder', 'Quality rerpots table column order', 'Specifies the order of the columns in the Quality Reports table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engqualityReportsRequired', 'eng', 'qualityReportsRequired', 'Quality report table required headers', 'Specifies the columns required in the Quality Reports table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engquantAggScale', 'eng', 'quantAggScale', 'Quantitative', 'The "quantAggScale" aggregation scale.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engquarRec', 'eng', 'quarRec', 'Quarantine recommendation', 'Advice that individuals exposed to a disease should isolate to prevent spread.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engr2', 'eng', 'r2', 'R squared', 'R-squared value of the calibration curve.', 'Used for storing calibration curve information, potentially also applicable for other curve types.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engr203m', 'eng', 'r203m', 'r203m delta-variant gene target', 'r203m delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engr346t', 'eng', 'r346t', 'R346T Mutation', 'The FLiRT/SLip variant mutation R346T.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engrainDpcr', 'eng', 'rainDpcr', 'Raindance digital PCR', 'Describes a PCR analysis done using Raindance''s digital PCR technology.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrainPerc', 'eng', 'rainPerc', 'dPCR Rain Percentage', 'The percentage of droplets tha fall between the major positive and negative population in digital droplet PCR.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrainy', 'eng', 'rainy', 'Rainy', 'Qualitative category for the weather measure, specifying a rainy day.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('engrandomSurv', 'eng', 'randomSurv', 'Random sampling surveillance program', 'A surveillance sampling strategy in which baseline is established at the beginning of a study or project by the selection of sample units via random sampling.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engranSeq', 'eng', 'ranSeq', 'Random sequencing selection method', 'Specifies the random selection method for sequencing', 'No primer set should be used if this is selected.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engratio', 'eng', 'ratio', 'Ratio', 'Ratio (unitless)', 'Report as a real number or fration. i.e 10:2 ratio is reported as 5. The specifics of the ratio (the numerator and the demoninator) are described in the measure.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engraw', 'eng', 'raw', 'Raw data', 'Raw data, without adjustment or additional treatment.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engraws', 'eng', 'raws', 'Raw wastewater', 'Raw wastes water sample', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engrawSeqProc', 'eng', 'rawSeqProc', 'Raw Sequence Data Processing Method', 'The software/library/pipeline used to process the raw sequencing data.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrawSeqProcSet', 'eng', 'rawSeqProcSet', 'Raw Sequence Data Processing Method Set', 'The category set of valid innput values for the software/library/pipeline used to process the raw sequencing data.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrawWW', 'eng', 'rawWW', 'Raw sewage at site', 'Wastewater without any form of treatment', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engrawWWdown', 'eng', 'rawWWdown', 'Raw sewage downstream from a site', 'Downstream from a site. See partType = rawWWup.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrawWWup', 'eng', 'rawWWup', 'Raw sewage upstream from a site', 'Upstream from a site. Used when there is not direct access to a site''s wastewater inconjuctiion with downstream sample. For example, if the site is a long-term care home, but ther is not access to the building or property cleanout. Use two sameple, one sample upstream and one sample downstream.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engraxML', 'eng', 'raxML', 'RaxML Software', 'A lineage or clade analysis software tool, popular for rapid maximum likelihood-based phylogenetic tree building with clade assignment.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrdrpIP2', 'eng', 'rdrpIP2', 'IP2 rdrp sars-cov-2 gene target', 'IP2 rdrp sars-cov-2 gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrdrpIP4', 'eng', 'rdrpIP4', 'IP4 rdrp sars-cov-2 gene target', 'IP4 rdrp sars-cov-2 gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engreadMapper', 'eng', 'readMapper', 'Sequencing read mapping software name', 'The name of the bioinformatics software tool used to align short DNA or RNA sequence reads (obtained from high-throughput sequencing technologies like Illumina, PacBio, or Oxford Nanopore) to a reference genome or transcriptome.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engreadMapperSet', 'eng', 'readMapperSet', 'Sequencing read mapping software set', 'The set of valid input values for the sequence read mapping software.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrecDate', 'eng', 'recDate', 'Date sample recieved', 'The date the sample was received at the laboratory for analysis.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, Update in line with Github Issue #211', NULL),
  ('engrecomb', 'eng', 'recomb', 'Recombinant Lineage Variant', 'A catch-all measure for viruses of non-specified and recombinant lineages, defined as those virsues wherein viruses of two different parent strains coinfect the same host cell and interact during replication to generate virus progeny that have some genes from both parents. Recombination generally occurs between members of the same virus type (e.g., between two influenza viruses or between two herpes simplex viruses). This is particularly common in the evolution of coronaviruses and sarbecoviruses.', 'Please bundle with a more general pathogen measure in a common measure set, so that it is clear to what species the recombinant virus belongs.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrecov', 'eng', 'recov', 'Recovered patients', 'Units for describing a population measure of patients who have recovered from a given disease.', 'Unit for a population or disease measure to explain population-level clinical effects.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engredundans', 'eng', 'redundans', 'Redundans', 'A sequencing software that is a genome assembler that reduces redundancy, useful for fragmented assemblies.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrefCamp', 'eng', 'refCamp', 'Refugee camp', 'A temporary, often makeshift shelter for persons displaced by war, political oppression, or for religious beliefs.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrefLink', 'eng', 'refLink', 'Reference link', 'Link to the reference material for a part. May link to literature on a method, measure, etc.', 'Link to standard operating procedure for a measure or part. Part reference is a reference to a technical document that describes the part in detail. The reference could be a URL, DOI, or reference to a techincal report.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engregular', 'eng', 'regular', 'Regular Pathogen Surveillance', 'A measure or sample taken for surveillance or epidemiology.', 'A ''regular'' measure is the default. Missing data will be recoded to this purpose.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engregularReportTableSet', 'eng', 'regularReportTableSet', 'Regular reports table set', 'Tables used for daily reporting of new measurements and information on sample collection.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrelationshipID', 'eng', 'relationshipID', 'Relationship between entities', 'Attribute for specifying the relationship between a sample subject and object.', 'Together with `sampleIDSubject` and `sampleRelID`, a row of the `sampleRelationships` should say: [sampleIDSubject] is a [sampleID] of [sampleIDObject]', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrelDateEnd', 'eng', 'relDateEnd', 'Measure relevance end date', 'The end date of the relevancy period of a measure - mostly for time-varrying metrics for sites or polygons.', 'NA', '2.3.0', '2.3.0', 'added in V2.3.0', NULL),
  ('engrelDateStart', 'eng', 'relDateStart', 'Measure relevance start date', 'The start date of the relevancy period of a measure - mostly for time-varrying metrics for sites or polygons.', 'NA', '2.3.0', '2.3.0', 'added in V2.3.0', NULL),
  ('engrelHum', 'eng', 'relHum', 'Relative humidity', 'The unit of relative humidity, or the air-water mixture. The ratio of the partial pressure of water vapor in the mixture to the equilibrium vapor pressure of water over a flat surface. of pure water at a given temperature.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('engrelHumidUnitSet', 'eng', 'relHumidUnitSet', 'Relative humidity unit set', 'Unit set for relative humidity measurements.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrelNR', 'eng', 'relNR', 'Relationship Not Reported', 'A relationship ID used in relationship tables across the ODM when two entities are related or connected in some way, but the actual nature of that relationship is not clear or reported.', 'This is mostly used when mapping data from other data formats wherein protocol relationships (for example) do not report clear temporal relationships or order to method steps.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrelSet', 'eng', 'relSet', 'General Relationship Set', 'set for valid values of relationshipID across all fields and tables.', 'NA', '2.2.3', '2.2.3', 'added in v 2.2.3', NULL),
  ('engrepGrab', 'eng', 'repGrab', 'Representative grab sample', 'A single large representative grab sample.', 'Deprecated in version 2, please do not use.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engreplicateSet', 'eng', 'replicateSet', 'Replicate Type set', 'The set for storing valid categorical values of replicate type.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrepNum', 'eng', 'repNum', 'replicate number', 'The replicate number for a Ct or Cq value - used for specifying out a protocol standard curve.', 'Only applies and used for aggregated standard curves, or curves that are used across multiple plates. Otherwise, these details can be captured in a measure report and specified by measure index.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrepOrg1', 'eng', 'repOrg1', 'Primary reporting authority ID', 'The primary or most responsible authority for rountine surveillance reports or findings, or where the site is located. ', 'Use the `organizations` table to describe attributes such as the name and address of the organziation. Use `orgType`, `orgLevel` and `orgSector` to describe additional attributes. For example,whether the organization is a government agency (`orgType`), local (`orgLevel`), or public health (`orgSector). If the attributes are not specified, the default is version 1.1.0 `publicHealthDepartment` defined as ''The public health department or region where the site is located. See also `healthReg` if there is a separate regional health care delivery authority.`', '1.1.0', '2.0.0', 'description wording, structure', NULL),
  ('engrepOrg2', 'eng', 'repOrg2', 'Secondary reporting authority ID', 'The secondary, additional or alternative authority for rountine surveillance reports or findings, or where the site is located. ', 'Use the `organizations` table to describe attributes such as the name and address of the organziation. Use `orgType`, `orgLevel` and `orgSector` to describe additional attributes. For example,whether the organization is a government agency (`orgType`), local (`orgLevel`), or public health (`orgSector). If the attributes are not specified, the default is version 1.1.0 `healthRegion`, The health planning authority where is site is located. defined as ''The public health department or region where the site is located.''', '1.1.0', '2.0.0', 'description wording, structure', NULL),
  ('engreportable', 'eng', 'reportable', 'Reportable', 'Flag for whether a measure is reportable or not, based on confidence in the measure and methods applied.', 'NA', '2.0.0', '2.1.0', 'added in V2.0.0', NULL),
  ('engreportDate', 'eng', 'reportDate', 'Report date', 'The date a measure was reported.', 'This date is the first date the laboratory or enity reported the measure findings to the public health or other enity who ordered the measure or is responsible for action. Use the analyses end date if the measure is part of a research study or other purpose that does not have a reporting entity.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engreporterIDDep', 'eng', 'reporterIDDep', 'Reporter ID depreciated', 'Unique identifier for the person or organization that is reporting the data.', 'NA', '1.1.0', '2.0.0', 'changed to contactID', NULL),
  ('engreportersDep', 'eng', 'reportersDep', 'Reporter table depreciated', 'The table that contains information about a reporter of a sample, method, measure, or attribute.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engreportTableInput', 'eng', 'reportTableInput', 'Report table input (wide table)', 'The short name for the listed source table.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engreportTableName', 'eng', 'reportTableName', 'Report table name (wide table)', 'The report table that the wide name calls from.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engrepType', 'eng', 'repType', 'Replicate Type', 'Attirbute of a sample, specifying whether the sample is unique, or a replicate. And if it is a replicate, what type of replicate is it?', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, GitHub issue #94', NULL),
  ('engres', 'eng', 'res', 'Reservoir', 'An artificial body of water, often contained by a dam, constructed for the purpose of water storage.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engresCosca', 'eng', 'resCosca', 'Resuspend COSCa filter collection', 'Nucleic acid extraction via resuspension of a sample collected using the COSCa ball method.', 'See partID = cosca for additional details.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engresearch', 'eng', 'research', 'Research sector or organization', 'Describes organizations whose focus is on research generation.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engresearchPurp', 'eng', 'researchPurp', 'Research purposes', 'Purpose of sampling/measure is for research.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engresFinderDtbase', 'eng', 'resFinderDtbase', 'ResFinder Database', 'nomenclaturre from the National Center for Biotechnology Information', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engresFinderSoft', 'eng', 'resFinderSoft', 'ResFinder Tool', 'Software tool that identifies acquired antimicrobial resistance genes in bacterial genomes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engresPerKm', 'eng', 'resPerKm', 'Residents per square kilometre', 'Residents per square kilometre.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engresPerMile', 'eng', 'resPerMile', 'Residents per square mile', 'Residents per square mile.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrestaurant', 'eng', 'restaurant', 'Restaurant ', 'A commercial establishment that prepares and serves food and beverages to customers.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrestrict', 'eng', 'restrict', 'Restricted data', 'Missing data is witheld because it is restricted access.', 'Missing value indicator for data that has been classified as resiticted, and not for sharing.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engresults', 'eng', 'results', 'Results tables', 'Tables used to record samples, measures and quality reports.', 'These tables are updated whenever a new sample is taken or a measure is reported. Quality reports are used to report quality assurance and quality control for samples and measures. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engresuspension', 'eng', 'resuspension', 'Resuspension method', 'Describes the method used for resuspending material.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engresusSet', 'eng', 'resusSet', 'Resuspension method set', 'The set to describe valid categorical values for the resuspension method.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engretainedElement', 'eng', 'retainedElement', 'Retained Element', 'The element retained after centrifugation, filtration, solid separation, etc.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engretElSet', 'eng', 'retElSet', 'Retained Element Set', 'The set for enumerating the valid possible values of the retained element method.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engretPond', 'eng', 'retPond', 'Retention pond', 'Retention pond', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engrev', 'eng', 'rev', 'Review of records', 'A review of records for determining site/polygon population.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrickettsia', 'eng', 'rickettsia', 'Rickettsia', 'Rickettsia', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engrickettsiaGrp', 'eng', 'rickettsiaGrp', 'Rickettsia Group', 'A group of measures/methods related to ricketsia parasites.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engriver', 'eng', 'river', 'River, natural water body', 'River, natural water body', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engrna', 'eng', 'rna', 'RNA Template', 'Ribonucleic Acid (RNA) template is used for PCR or sequencing work.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engrnaDepl', 'eng', 'rnaDepl', 'rRNA Depletion Method', 'Removal of background RNA for the purposes of enriching the genomic target.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrnaLater', 'eng', 'rnaLater', 'RNAlater', 'A buffer solution/medium the stabilizes RNA and DNA in samples, effective for preserving nucleic acids in wastewater.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrnaseP', 'eng', 'rnaseP', 'Ribonuclease P (RNase P)', 'Ribonuclease P (RNase P) (usually measured as a human fecal indicator)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engroad', 'eng', 'road', 'Road ', 'A paved or unpaved pathway designed for vehicular and pedestrian travel.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engroadside', 'eng', 'roadside', 'Roadside ', 'The area adjacent to a road, including sidewalks, shoulders, or drainage ditches.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engrole', 'eng', 'role', 'Role of contact', 'Specifies the organizational role of a given contact.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
