  ('engrsvGrp', 'eng', 'rsvGrp', 'Respiratory syncytial virus (RSV) Group', 'Human Respiratory Syncytial virus (RSV).', 'Refer to Group = `rsvA` and `rsvB` for measure that are specific to RSV A or RSV B, respectively. ', '2.0.0', '2.1.2', 'added in V2.0.0', NULL),
  ('engrsvMe', 'eng', 'rsvMe', 'Respiratory syncytial virus', 'Human Respiratory Syncytial virus (RSV), generic measure.', 'Refer to Group = `rsvA` and `rsvB` for measure that are specific to RSV A or RSV B, respectively. ', '2.0.0', '2.1.2', 'added in V2.0.0', NULL),
