  ('engstag', 'eng', 'stag', 'Stagnant', 'A quality of a body of water wherein it has no current or flow.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstamp', 'eng', 'stamp', 'Statistical Analysis of Metagenomic Profiles (STAMP) Software', 'A lineage or clade analysis software tool for analyzing taxonomic profiles and differentiating clades.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstandard', 'eng', 'standard', 'Standard for Data Adjustment', 'A field where one can categorically record the standard to which something is being standardized (ie. PMMoV, Crassphage, Flow, etc.) or smoothed (ie. bayesian smoothing, central average smoothing, 7-days, time, etc.).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstandardConc', 'eng', 'standardConc', 'Standard concentrations class', 'Measures and methods relating to standard conentrations.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstandardCurve', 'eng', 'standardCurve', 'Standard curve class', 'Measures and methods relating to generating or recording a standard curve.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstandardization', 'eng', 'standardization', 'Standardization Calculation Type', 'A method used to scale data to a common range or distribution, often to enable fair comparisons across different variables, time periods, or locations.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstaphGrp', 'eng', 'staphGrp', 'Staphylococcus Group', 'A group of measures/methods related to staphylococcus bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstar', 'eng', 'star', 'STAR (Spliced Transcripts Alignment to a Reference)', 'STAR (Spliced Transcripts Alignment to a Reference). A general-purpose read mapper. Fast aligner designed for RNA-seq, supports spliced alignment. Best for: Transcriptome data analysis.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstarAMR', 'eng', 'starAMR', 'StarAMR Software', 'Software tool that is used to detect AMR genes in genome assemblies.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstateProvLevel', 'eng', 'stateProvLevel', 'Departments, states, or provinces', 'Departments, states, or provinces', 'NA', '2.0.0', '3.0.0', 'Reactivated as organization level and sector categorical inputs, rather than attributes.', NULL),
  ('engstateProvReg', 'eng', 'stateProvReg', 'State, Province, or Region', 'The state, province, or region where a site or organization is located; part of the address.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engstatus', 'eng', 'status', 'Status', 'Whether the part is still active and can be used in the most current ODM version. Values are ''active'' or ''inactive''.', 'The status of the part or list. ''active'' means the part is used in the dictionary version. ''inactive'' means the part has been retired and not longer used in the version.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstatusSet', 'eng', 'statusSet', 'Status set', 'A set for partID = Status to indicate whether a part is in current use or not.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstd', 'eng', 'std', 'Standard sample', 'Denotes a standard sample replicate.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstdConcentrationUnitSet', 'eng', 'stdConcentrationUnitSet', 'Standard concentration unit set', 'Unit set for concentration measurements.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstdCurveMet', 'eng', 'stdCurveMet', 'Standard Curve Calculation Method', 'Describes the specific approach used for calculating a standard curve.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstdCurveSet', 'eng', 'stdCurveSet', 'Standard Curve Calculation Set', 'The set capturing containing all of the valid methods for the PCR standard curve calculations.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstec', 'eng', 'stec', 'Shiga-toxin-producing Escheria coli (STEC)', 'Shiga-toxin-producing Escheria coli (STEC).', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engsTemp', 'eng', 'sTemp', 'Storage temp', 'Temperature that the sample is stored at in Celsius.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engstepID', 'eng', 'stepID', 'Protocol Step ID', 'The unique identifier for a specific protocol step.', 'Protocol Steps are the component parts of a larger protocols, the latter being linked to specific measure reports.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepIDObj', 'eng', 'stepIDObj', 'Step ID Object', 'The object of the relationship between one protocol step and another step or protocol, within a given protocol ID container.', 'Populate this field using Protocol Step ID (partID = stepID). Together with `protocolIDSub` or `stepIDSub` and `relationshipID` the row of `protocolRelationships` should say: [protocolIDSubject or stepIDSubject]  [relationshipID] [protocolIDObject or stepIDObject]. Ex: stepIDSubject  precedes protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepIDSub', 'eng', 'stepIDSub', 'Step ID Subject', 'The subject of the relationship between one protocol step and another step or protocol, within a given protocol ID container.', 'Populate this field using Protocol ID (partID = stepID). Together with `protocolIDSub` or `stepIDSub` and `relationshipID` the row of `protocolRelationships` should say: [protocolIDSubject or stepIDSubject]  [relationshipID] [protocolIDObject or stepIDObject]. Ex: stepIDSubject  precedes protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepProvenanceID', 'eng', 'stepProvenanceID', 'Method step parent ID', 'A method step that served as a basis for another method step. This may be due to version changes, or a referencing a method set that was later adapted.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstepVer', 'eng', 'stepVer', 'Protocol step version', 'Specifies the version of a given protocol step.', 'Version of the method step. Semantic versioning is recommended.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engstEr', 'eng', 'stEr', 'Standard Error', 'The standard error of a series of measurements.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstercobilin', 'eng', 'stercobilin', 'Stercobilin', 'Stercobilin is a tetrapyrrolic bile pigment and is one end-product of heme catabolism. It is the chemical responsible for the brown color of human feces and was originally isolated from feces in 1932.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstoMed', 'eng', 'stoMed', 'Sample Storage Medium', 'The medium used to store a sample before final analysis.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstoMedSet', 'eng', 'stoMedSet', 'Sample Storage Medium Set', 'The set of valid categorical inputs for the stoMed field.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstormy', 'eng', 'stormy', 'Stormy Weather', 'Stormy weather', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstorTempDef', 'eng', 'storTempDef', 'Sewer network file blob', 'A file blob that has any detailed information about the sewer network associated with the site (any format).', 'Deprecated in version 2, please do not use. Refer to WKT and EPSG instead.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('engstoTim', 'eng', 'stoTim', 'Storage time', 'Length of time that a sample was in storage.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engstr', 'eng', 'str', 'Stream', 'A watercourse which is linear and flows across the solid portion of a planetary surface.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstrainID', 'eng', 'strainID', 'Strain ID', 'The strain identifier for a given organism.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstrainPhIAb', 'eng', 'strainPhIAb', 'StrainPhlAn Software', 'A lineage or clade analysis software tool within MetaPhlAn for strain-level lineage analysis from metagenomic data.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engstrepGrp', 'eng', 'strepGrp', 'Streptococcus Group', 'A group of measures/methods related to streptococcus bacteria.', 'Used to describe the organism information for general measures.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engstrepPneu', 'eng', 'strepPneu', 'Streptococcus pneumoniae', 'Streptococcus pneumoniae', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsts', 'eng', 'sts', 'Sodium Thiosulfate Solution', 'A buffer solution/medium that neutralizes residual chlorine in wastewater samples, ensuring microbial viability.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsu', 'eng', 'su', 'Summary worksheet Shorthand', 'The abbreviated short name used to reference the Summary sheet of the dictionary.xlxs file.', 'sheet support', '2.2.2', '3.0.0', 'depreciated in version 3', NULL),
  ('engsubread', 'eng', 'subread', 'Subread', 'Subread. A general-purpose read mapper. Includes the subread-align algorithm for mapping DNA and RNA reads. Best for: High-throughput data with a balance of speed and accuracy.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsubSamp', 'eng', 'subSamp', 'Subsample (General)', 'A general replicate type for a subsample not otherwise defined.', 'Use when additional details about the replicate are not available.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsuburban', 'eng', 'suburban', 'Suburban', 'Suburban populated area type', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsubVar', 'eng', 'subVar', 'Sub-variant or lineage', 'A unit used to report a specific genetic lineage, or to specify that a reported variant is a sub-variant of another.', 'Combine in a measure report if necessary.', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #120', NULL),
  ('engsuc', 'eng', 'suc', 'Sucralose', 'Sucralose (usually measured as a human fecal chemical indicator)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsum14', 'eng', 'sum14', 'Rolling sum of previous 14 days', 'The rolling sum of case counts/some kind of count over the previous 14 days.', 'Aggregation for a population or disease measure to explain population-level clinical effects.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engsumm', 'eng', 'summ', 'Summary', 'Short description of the assay and how it is different from the other assay methods.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engsummary', 'eng', 'summary', 'Summary worksheet', 'Summary sheet of the dictionary.xlxs file.', 'The summary sheet contains versioning and changelog.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsunny', 'eng', 'sunny', 'Sunny', 'Qualitative category for the weather measure, specifying a clear and sunny day.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, github issue #124 and #204', NULL),
  ('engsureSelectXThs2', 'eng', 'sureSelectXThs2', 'SureSelect XT HS2 DNA Library Preparation Kit', 'SureSelect XT HS2 DNA Library Preparation Kit by Agilent. A high-sensitivity library prep kit with target capture capabilities.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsurf', 'eng', 'surf', 'Surface compartment', 'A measure or observation made from a substance on a surface.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsurface', 'eng', 'surface', 'Other surface', 'Surface other than floor or desk.', 'See also categories for floor and desk. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsurfaceCompartmentSet', 'eng', 'surfaceCompartmentSet', 'Surface compartment set', 'A compartment set for measures and methods in the surface compartment.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsurfaceWaterCompartmentSet', 'eng', 'surfaceWaterCompartmentSet', 'Surface and water compartment set', 'A compartment set for measures and methods in the surface or water compartments.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsurfSw', 'eng', 'surfSw', 'Surface swab', 'Surface swab.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engsurvAlert', 'eng', 'survAlert', 'Surveillance alert', 'A public health action type wherein authorities have made a decision about surveillance and communicated the alert.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsurvAlertSet', 'eng', 'survAlertSet', 'Surveillance Alert Value Set', 'A set of valid categories for the public health action field, where the action type is ''surveillance alert''.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsurvLevel', 'eng', 'survLevel', 'Surveillance Level', 'The scale or level of surveillance being done at a site. Ie. Is it institutional, is it only for a single building, or is it for a whol municipality.', 'Mostly for use when a polygon is not reported. But situations of community surveillance, ideally a polygon should also be supplied.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engsurvLevelSet', 'eng', 'survLevelSet', 'Surveillance Level Set', 'The list of valid categories for the survLevel measure.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engswgTrck', 'eng', 'swgTrck', 'Sewage truck', 'Sewage truck', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engswift2STurbo', 'eng', 'swift2STurbo', 'Swift 2S Turbo DNA Library Kit', 'Swift 2S Turbo DNA Library Kit by Swift Biosciences. A fast library prep kit workflow with robust performance for low-input DNA.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engswrSed', 'eng', 'swrSed', 'Sewer sediment', 'Sediments obtained in sewer', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('engswrSet', 'eng', 'swrSet', 'Sewer catchment area', 'Sewer catchment area.', 'NA', '1.0.0', '2.0.0', 'Name Change (from Polygon Type)', NULL),
  ('engsynthetic', 'eng', 'synthetic', 'Synthetic sample', 'A synthetic or artificially generated sample.', 'Synthetic samples are artificially created by mixing known quantities of target substances or organisms with clean water, often in a laboratory setting. These samples are used as controls, benchmarks, or calibration standards during the analysis process to ensure accurate and reliable results. For instance, a synthetic sample containing a known concentration of a specific pollutant might be used to calibrate analytical equipment or to test the efficiency of a new detection method.', '2.0.0', '2.0.0', 'added in V2.0.0, GitHub issue #94', NULL),
  ('engt19r', 'eng', 't19r', 't19r delta-variant gene target', 't19r delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engt3646a', 'eng', 't3646a', 't3646a delta-variant gene target', 't3646a delta-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engt547k', 'eng', 't547k', 't547k omicron-variant gene target', 't547k omicron-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engt9i', 'eng', 't9i', 't9i omicron-variant gene target', 't9i omicron-variant mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtables', 'eng', 'tables', 'Tables', 'Tables are where measures, methods and attributes are recorded. Tables represent the main entities of the environmental surveillance. There', 'An example of a  table is `site` a collection of attributes such as site name and address to describe where environment samples are taken. PHES-ODM has report tables, but users can create their own tables as well.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtableSet', 'eng', 'tableSet', 'Table column set', 'The set for valid inputs in table columns.', 'These categories are used in the parts list for columns named after tables to indicate the position and function of a given part in the entity relationship diagram of the data model.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtableSupport', 'eng', 'tableSupport', 'Table Support', 'Parts designed to support the metadata definition oftables in the parts table.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtaqpatN', 'eng', 'taqpatN', 'TaqPath N sars-cov-2 gene target', 'TaqPath N sars-cov-2 mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtaqpatS', 'eng', 'taqpatS', 'TaqPath S sars-cov-2 gene target', 'TaqPath N sars-cov-2 mutation gene target', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtargetSurv', 'eng', 'targetSurv', 'Targeted surveillance program', 'A surveillance sampling strategy in which an aspired outcome is explicitly stated.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtargSurv', 'eng', 'targSurv', 'Targetted surveillance initiated', 'Monitoring focused on a specific population, location, or risk factor.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtaxonium', 'eng', 'taxonium', 'Taxonium Software', 'Taxonium - A scalable tool for viewing and analyzing large phylogenetic trees, including clade annotations.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtds', 'eng', 'tds', 'Total Dissolved Solids (TDS)', 'Total dissolved solids', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtechRep', 'eng', 'techRep', 'Technical replicate', 'A sample that comes from the same biological or environmental source (e.g., the same extracted DNA, the same RNA aliquot, or the same water sample). Helps detect inconsistencies due to pipetting errors, instrument fluctuations, or reagent inconsistencies, rather than biological variation.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtemp', 'eng', 'temp', 'Sample temperature', 'Temperature of the sample measured in degrees Celcius', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engtemperature', 'eng', 'temperature', 'Temperature class', 'Measures and methods related to temperatures.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtemperatureUnitSet', 'eng', 'temperatureUnitSet', 'Temperature unit set', 'Unit set for temperature measurements.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtemplateSheetSet', 'eng', 'templateSheetSet', 'Template Sheet Set', 'Worksheets in the full generic ODM surveillance template (all tables).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtempSet', 'eng', 'tempSet', 'Template Set', 'The organizing set for templates.', 'NA', '2.2.0', '2.2.0', 'Added in V 2.2.0', NULL),
  ('engtempType', 'eng', 'tempType', 'Nucelic Acid Template Type', 'Specifies whether a PCR or sequencing used RNA or DNA as the template for the reaction.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engtempVol', 'eng', 'tempVol', 'Nucleic acid template volume', 'The volume of DNA or RNA template used for PCR. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engterminal', 'eng', 'terminal', 'Airport terminal', 'Airport terminal sample shed category type', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtesDate', 'eng', 'tesDate', 'Test date', 'Date that the covid-19 test was performed.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('engtest', 'eng', 'test', 'Number of tests performed', 'Number of tests performed.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('engtesting', 'eng', 'testing', 'Protocol testing', 'A measure or sample taken to test a new method. These measures are typically used for internal lab uses and not reported to external partners.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtetAMRGrp', 'eng', 'tetAMRGrp', 'Tetracycline Anti-microbial resistance Group', 'The group for measures and methods pertaining to tetracycline-related anti-microbial resistance.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engtetW', 'eng', 'tetW', 'TetW Tetracycline-resistance gene target', 'The tetW tetracycline anti-microbial resistance gene target.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engthermCyc', 'eng', 'thermCyc', 'Thermal cyclers', 'A thermal cycler instrument, used to perform temperature-controlled reactions for PCR.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engthermMag', 'eng', 'thermMag', 'thermo magmax microbiome ultra nucleic acid isolation kit', 'Nucleic acid extraction performed using the thermo magmax microbiome ultra nucleic acid isolation kit.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engthermMagmax', 'eng', 'thermMagmax', 'thermo magmax viral/pathogen nucleic acid isolation kit', 'thermo magmax viral/pathogen nucleic acid isolation kit', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('engthreatDes', 'eng', 'threatDes', 'Threat designation', 'A public health action type wherein a threat level is determined and communicated by authorities.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engthreatDesSet', 'eng', 'threatDesSet', 'Threat designation Value Set', 'A set of valid categories for the public health action field, where the action type is ''threat designation''.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engthreatTarget', 'eng', 'threatTarget', 'Public health threat targeted by action', 'The pathogen or variant for which the designation or action is being taken.', 'Populated by a ''measurement'' part type.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engthruPLEX', 'eng', 'thruPLEX', 'ThruPLEX DNA-seq Kit', 'ThruPLEX DNA-seq Kit by Takara Bio. A low-input library prep kit with fast, three-step protocol.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtHub', 'eng', 'tHub', 'Transport hub - General', 'A tansport hub not otherwise specified. i.e. a place where passengers and cargo are exchanged between vehicles or/and between transport modes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtimeClass', 'eng', 'timeClass', 'Time class', 'Measures and methods relating to time.', 'NA', '2.0.0', '3.0.0', 'partID changed from "time" to "timeClass"', NULL),
  ('engtimePr', 'eng', 'timePr', 'Time proportional sample', 'A time proportional composite sample generally collected by an autosampler.', 'Use collectionPeriod to describe how many hours the sample was taken.', '1.0.0', '2.0.0', 'Removed time period. Use collection period (collectPer) = 24 for 24hr sample', NULL),
  ('engtimeStand', 'eng', 'timeStand', 'Time standardized', 'This data treatment standardizes the measurement value against time.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('engtimeUnitSet', 'eng', 'timeUnitSet', 'Time unit set', 'The unit set for measures of time.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtkn', 'eng', 'tkn', 'Total Kjeldahl Nitrogen', 'A measure of Total Kjeldahl Nitrogen; ie. the sum of nitrogen bound in organic substances, nitrogen in ammonia (NH3-N) and in ammonium (NH4+-N) in the chemical analysis of soil, water, or waste water.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('engtld', 'eng', 'tld', 'Country code top-level domain', 'The internet top-level domain generally used or reserved for a country, sovereign state, or dependent territory identified with a country code.', 'Preprogrammed into dictionary tables, not editable by users.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('engtn', 'eng', 'tn', 'Total Nitrogen', 'Total nitrogen concentration, as N.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('engtophat', 'eng', 'tophat', 'TopHat', 'TopHat. A general-purpose read mapper. An older RNA-seq aligner, splicing-aware. Replaced by HISAT2 in most workflows. Best for: Historical RNA-seq studies.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
