  ('fraamDefDep', 'fra', 'amDefDep', 'ID méthode d''analyse par défaut', 'Identifiant de la méthode d''analyse utilisée par défaut quand une nouvelle mesure est créé par ce laboratoire. Se référer é la colonne "assayMethodID" dans la table "AssayMethod"', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('fraamiconUf', 'fra', 'amiconUf', 'Ultrafiltration Amicon', 'Ultrafiltration Amicon', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('fraamiMP96', 'fra', 'amiMP96', 'Filtre Amicon, extrait avec MP96', 'Extraction de l''acide nucléique, généralement utilisée pour la fraction liquide d''un échantillon d''eau usée, en utilisant la filtration amicon et en utilisant un MP96 pour l''extraction finale.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
