  ('frahusb', 'fra', 'husb', 'Élevage', 'Une activité d''élevage animal a eu lieu en amont du site d''échantillonnage.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('frahySel', 'fra', 'hySel', 'Méthode de sélection hybride', 'Sélection par hybridation dans un réseau ou une solution pour l''enrichissement de la cible génomique.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('frai1566v', 'fra', 'i1566v', 'i1566v cible de gène de la variante omicron', 'Gène cible i1566v de la variante omicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
