  ('fralibPrepInst', 'fra', 'libPrepInst', 'Instruments de préparation de bibliothèques', 'Des instruments pour la préparation de banques de séquençage, par exemple des plateformes d''automatisation comme l''Illumina NeoPrep.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fralibraryKit', 'fra', 'libraryKit', 'Kit de préparation de bibliothèque', 'Nom du kit de préparation de bibliothèque d''ADN/ARN utilisé pour générer la bibliothèque séquencée.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fralibraryKitSet', 'fra', 'libraryKitSet', 'Ensemble de kits de préparation de bibliothèque', 'Ensemble valide de valeurs catégorielles pour les kits de préparation de bibliothèque de séquençage.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
