  ('franaGroup', 'fra', 'naGroup', 'Groupe non applicable', 'Non applicable. ', 'Utilisez "non applicable" lorsqu''il n''y a pas de groupe pour la pièce.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franame', 'fra', 'name', 'Nom', 'Nom d''un domaine, d''un spécimen, d''un groupe, d''une classe, d''un attribut, d''une unité, d''une nomenclature ou d''une autre entité.', 'Nom d''une entité. Utilisez un préfixe pour distinguer les noms des différentes tables de rapport. Voir la liste des noms entièrement spécifiés (FSN). Par exemple : Si-name = nom du site, Po-name = nom du polygone, Or-name = nom de l''organisation, Me-name = nom de la méthode. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franameEngl', 'fra', 'nameEngl', 'Nom anglais du pays', 'Nom en anglais d''un pays donné.', 'Préprogrammés dans les tables du dictionnaire, ils ne sont pas modifiables par les utilisateurs.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('franameOfficial', 'fra', 'nameOfficial', 'Nom officiel de l''État', 'Nom officiel en anglais d''un État donné.', 'Préprogrammés dans les tables du dictionnaire, ils ne sont pas modifiables par les utilisateurs.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('franan', 'fra', 'nan', 'Pas un numéro', 'Le résultat d’une mesure n’est pas un numéro valide (plus ou moins l''infini, une erreur, …)', 'Indicateur de valeurs manquantes lorsqu''une valeur numérique est attendue mais n''est pas donnée.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franaNomenclature', 'fra', 'naNomenclature', 'Nomenclature non applicable', 'Non applicable. ', 'Utilisez "sans objet" lorsqu''il n''y a pas de nomenclature pour la pièce.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('frananoPlot', 'fra', 'nanoPlot', 'NanoPlot', 'Un outil de pipeline de contrôle qualité pour les données de séquençage qui effectue des visualisations pour l''évaluation de la qualité des données à lecture longue, en particulier celles provenant d''Oxford Nanopore.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('franaSpecimen', 'fra', 'naSpecimen', 'Spécimen non applicable', 'Non applicable. ', 'Utilisez "non applicable" lorsqu''il n''y a pas de spécimen pour la partie.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franaSpecimenSet', 'fra', 'naSpecimenSet', 'Ensemble de spécimen non applicable', 'Non applicable. ', 'Utilisez "non applicable" lorsqu''il n''y a pas de spécimen pour la partie.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franatName', 'fra', 'natName', 'Nom natif de la langue', 'Le nom natif de la langue, c''est-à-dire le nom donné à la langue par ses locuteurs.', 'Partie des metedata d''un languageID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
