  ('franb181V', 'fra', 'nb181V', 'Variante NB.1.8.1 (Nimbus)', 'Le variant Nimbus du SARS-CoV-2 (NB.1.8.1), descendant du variant recombinant XDV.1.5.1.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('franBPSeq', 'fra', 'nBPSeq', 'Nombre de paires de bases séquencées', 'Le nombre total de paires de bases générées par le processus de séquençage.', 'Fournir une valeur numérique (pas besoin d''inclure les unités).', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
