  ('franH4N', 'fra', 'nH4N', 'Azote Ammoniacal', 'Concentrsation d''azote ammoniacal, exprimé en N.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franight', 'fra', 'night', 'Nuit', 'L''échantillon a été prélevé la nuit, entre le coucher et le lever du soleil.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('franiid19', 'fra', 'niid19', 'Gène ciblé niid_2019-ncov_n de SRAS-CoV-2', 'Gène cible niid_2019-ncov_n de SRAS-CoV-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franimbusGrp', 'fra', 'nimbusGrp', 'Groupe de variantes Nimbus du SARS-CoV-2', 'Un groupe de mesures et méthodes liées au variant Nimbus du SARS-CoV-2.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
