  ('franoliquid', 'fra', 'noliquid', 'Pas de concentration du liquide, le liquide est recombiné avec les solides séparés.', 'Pas de concentration du liquide, le liquide est recombiné avec les solides séparés.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('franomenclature', 'fra', 'nomenclature', 'Nomenclature', 'Un système de classification pour rendre compte de la classe de mesures. ', 'Actuellement utilisé uniquement pour classe = variante. Pangolin, Nexclade, WHO sont les trois nomeclactures utilisées pour rapporter les variantes.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franomenclatures', 'fra', 'nomenclatures', 'Type de nomenclature', 'Un système de classification pour rendre compte de la classe de mesures. ', 'Voir partID = nomenclatureID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('franone', 'fra', 'none', 'Aucun milieu de stockage des échantillons utilisé', 'Aucun milieu de conservation des échantillons utilisé', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('franoRain', 'fra', 'noRain', 'Pas de pluie', 'Catégorie qualitative pour la mesure météorologique, spécifiant l''absence de précipitations pour un jour donné.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
