  ('fraseptTnk', 'fra', 'septTnk', 'Fosse septique', 'Fosse septique.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('fraseqAss', 'fra', 'seqAss', 'Logiciel d''assemblage de séquences', 'Le nom du logiciel/kit d''outils/pipeline utilisé pour assembler des séquences à partir de lectures.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fraseqAssLen', 'fra', 'seqAssLen', 'Longueur d''assemblage de la séquence', 'Longueur du génome généré par l''assemblage de lectures à l''aide d''un échafaudage ou par cartographie basée sur des références.', 'Fournir une valeur numérique (pas besoin d''inclure les unités).', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fraseqAssSet', 'fra', 'seqAssSet', 'Ensemble de logiciels d''assemblage de séquences', 'Ensemble valide de valeurs catégorielles pour les méthodes logicielles d''assemblage de séquences.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fraseqContam', 'fra', 'seqContam', 'Séquence contaminée', 'La séquence est contaminée.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('fraseqKitRmdup', 'fra', 'seqKitRmdup', 'SeqKit rmdup', 'Une méthode de déduplication qui fonctionne dans SeqKit pour la suppression des doublons dans les fichiers FASTA/FASTQ.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('fraseqKitStats', 'fra', 'seqKitStats', 'SeqKit stats', 'Partie de SeqKit, un outil de pipeline QC pour les données de séquençage qui fournit un résumé des mesures de séquence telles que la longueur, la teneur en GC et la qualité.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
