  ('spacdcCovN1IDTRev', 'spa', 'cdcCovN1IDTRev', 'Cebador reverso 2019-nCoV_N1 (IDT)', '2019-nCoV_N1 cebador inverso (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdcCovN2IDTFor', 'spa', 'cdcCovN2IDTFor', 'Cebador directo 2019-nCoV_N2 (IDT)', '2019-nCoV_N2 cebador directo (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdcCovN2IDTProbe', 'spa', 'cdcCovN2IDTProbe', 'Sonda 2019-nCoV_N2 (IDT)', '2019-nCoV_N2 sonda (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdcCovN2IDTRev', 'spa', 'cdcCovN2IDTRev', 'Cebador reverso 2019-nCoV_N2 (IDT)', '2019-nCoV_N2 cebador inverso (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdcCovN3IDTFor', 'spa', 'cdcCovN3IDTFor', 'Cebador directo 2019-nCoV_N3 (IDT)', '2019-nCoV_N3 cebador directo (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdcCovN3IDTProbe', 'spa', 'cdcCovN3IDTProbe', 'Sonda 2019-nCoV_N3 (IDT)', '2019-nCoV_N3 sonda (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdcCovN3IDTRev', 'spa', 'cdcCovN3IDTRev', 'Cebador reverso 2019-nCoV_N3 (IDT)', '2019-nCoV_N3 cebador inverso (IDT)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacdHIT', 'spa', 'cdHIT', 'CD-HIT', 'Una aplicación de procesamiento de datos de secuenciación que agrupa y elimina secuencias duplicadas, útil para la desreplicación.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacDiff', 'spa', 'cDiff', 'Clostridium difficile', 'Clostridium difficile', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacDip', 'spa', 'cDip', 'Corynebacterium diphtheriae', 'Corynebacterium diphtheriae', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacecill21', 'spa', 'cecill21', 'Acuerdo de licencia de software libre CeCILL v2.1', 'La licencia para la medida o el conjunto de datos se gestiona bajo el Acuerdo de licencia de software libre CeCILL v2.1.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacel', 'spa', 'cel', 'Grados Celsius', 'Grados Celsius.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('spacelera', 'spa', 'celera', 'Ensamblador Celera', 'Un software de secuenciación que se desarrolló inicialmente para el Proyecto Genoma Humano y que todavía se utiliza en algunos flujos de trabajo para genomas grandes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacensus', 'spa', 'census', 'Censo de población', 'Censo del gobierno u otra agencia para determinar la población del sitio/polígono.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacent', 'spa', 'cent', 'Centrifugación', 'Describe la separación de sólidos de una muestra de aguas residuales mediante centrifugación. Probablemente relacionado con otros pasos del método previos al análisis.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacentriconUf', 'spa', 'centriconUf', 'Ultrafiltración Centricon', 'Ultrafiltración Centricon.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spacentriInst', 'spa', 'centriInst', 'Centrífugas', 'Instrumentos de centrifugación; separan los sólidos de los líquidos o concentran las partículas.', 'Las ultracentrífugas son una opción de tipo de instrumento independiente.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacentSpeed', 'spa', 'centSpeed', 'Velocidad de centrifugación', 'Velocidad de centrifugación', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaceres', 'spa', 'ceres', 'Nanotrampa Ceres', 'Ceres nanotrap.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spacesspit', 'spa', 'cesspit', 'Pozo séptico', 'En algunos contextos, los términos «pozo negro», «fosa séptica» y «pozo de absorción» tienen varios significados: se utilizan para describir un tanque de almacenamiento subterráneo (sellado en la parte inferior) o un pozo de absorción (sin sellar en la parte inferior). Un pozo negro puede utilizarse para la recogida y el almacenamiento temporal de heces, excrementos o lodos fecales como parte de un sistema de saneamiento in situ y tiene algunas similitudes con las fosas sépticas o los pozos de absorción. ', 'NA', '2.2.3', '2.2.3', 'added in v2.2.3', NULL),
  ('spacfu', 'spa', 'cfu', 'Unidades formadoras de colonias', 'Unidades formadoras de colonias', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacfu100', 'spa', 'cfu100', 'UFC por 100 ml', 'Unidades formadoras de colonias por cada 100 ml de muestra filtrada.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('spacfugTS', 'spa', 'cfugTS', 'Unidades formadoras de colonias por gramos de sólidos totales', 'Unidades formadoras de colonias por gramos de sólidos totales (UFC/gST)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacfumL', 'spa', 'cfumL', 'Unidades formadoras de colonias por mililitro', 'Unidades formadoras de colonias por mililitro (UFC/ml)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spachanges', 'spa', 'changes', 'Columna de cambios', 'Una columna para registrar los cambios con respecto a una versión anterior.', 'Utilice esta columna como registro de cambios abreviado para el desarrollo del diccionario.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacharLength', 'spa', 'charLength', 'longitud de caracteres', 'El número de caracteres utilizados para los nombres amplios.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spache', 'spa', 'che', 'Químico', 'Compuesto químico.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spachemSurv', 'spa', 'chemSurv', 'Vigilancia de contaminantes químicos', 'El objetivo del muestreo/medición es detectar la presencia de determinadas sustancias químicas o contaminantes químicos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spachemVir', 'spa', 'chemVir', 'Kit chemagic viral dna/rna 300', 'Extracción de ácido nucleico realizada con el kit Chemagic Viral DNA/RNA 300.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spachewBBACA', 'spa', 'chewBBACA', 'ChewBBACA', 'ChewBBACA. Enfoque: genoma central MLST (cgMLST) con análisis de serotipificación opcional. Aplicaciones: patógenos bacterianos de amplio espectro. Características: eficiente con grandes conjuntos de datos y altamente personalizable.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spachikungunyaGrp', 'spa', 'chikungunyaGrp', 'Grupo Chikungunya', 'Grupo de medidas/métodos relacionados con el virus chikungunya.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spachikv', 'spa', 'chikv', 'Virus del chikungunya (CHIKV)', 'Virus chikungunya (CHIKV)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spachild', 'spa', 'child', 'Relación filial', 'Indica que se trata de una muestra generada a partir de otra(s) muestra(s), ya sea por agrupación o por submuestreo.', 'NA', '1.0.0', '2.0.0', 'changed to a relationshipID value.', NULL),
  ('spachlamydia', 'spa', 'chlamydia', 'Clamidia', 'Clamidia', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spachlamydiaGrp', 'spa', 'chlamydiaGrp', 'Grupo Clamidia', 'Grupo de medidas/métodos relacionados con la bacteria clamidia.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacity', 'spa', 'city', 'Ciudad', 'Ciudad en la que se encuentra un sitio u organización; parte de la dirección.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spacJejuni', 'spa', 'cJejuni', 'Bacteria Campylobacter jejuni', 'Gen objetivo/medición de Campylobacter jejuni', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spacK', 'spa', 'cK', 'Clave compuesta', 'Clave compuesta para una tabla.', 'Todas las tablas de informes tienen una clave principal: la clave compuesta actúa como clave principal, pero se produce como una combinación de otros campos. Cada fila de una tabla de informes tiene un identificador único registrado en la clave principal/clave compuesta. ', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spacl', 'spa', 'cl', 'Nombre corto de tabla de cálculos', 'Nombre abreviado utilizado para hacer referencia a la tabla en la que se registran los datos sobre los tratamientos y cálculos aplicados a las mediciones y los valores comunicados.', 'tabla', '2.3.0', '2.3.0', 'added in V2.3.0', NULL),
  ('spacladeAn', 'spa', 'cladeAn', 'Software de análisis de linaje o clado', 'Herramienta de software o canalización para determinar el clado o linaje de un organismo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacladeAnSet', 'spa', 'cladeAnSet', 'Conjunto de software de análisis de linaje o clado', 'Conjunto de categorías válidas para los tipos de software de análisis de linajes o clados.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclari', 'spa', 'clari', 'Muestra clarificada', 'Muestra clarificada.', 'NA', '1.0.0', '2.0.0', 'NA', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('spaclark', 'spa', 'clark', 'CLARK', 'Un software de deshosting que clasifica las lecturas taxonómicamente, lo que ayuda a filtrar las lecturas del huésped en los datos metagenómicos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclass', 'spa', 'class', 'Clase', 'Un identificador único para una clase, que es similar a un subgrupo; es una forma de agrupar partes dentro de un grupo determinado. Un grupo puede tener una o más clases para describir diferentes partes de la clase. ', 'Actualmente, la clase solo se utiliza para biol', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaclasses', 'spa', 'classes', 'Clases', 'Una clase es una colección de una o más medidas o métodos relacionados dentro de un grupo. Un grupo puede tener una o más clases para describir diferentes partes de la clase. ', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacleanPlex', 'spa', 'cleanPlex', 'Kit de preparación de biblioteca de ADN CleanPlex', 'Kit de preparación de bibliotecas de ADN CleanPlex de Paragon Genomics. Un kit de enriquecimiento de bibliotecas optimizado para alta sensibilidad y baja entrada.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclermonTyp', 'spa', 'clermonTyp', 'ClermonTyping', 'ClermonTyping. Enfoque: MLST y tipificación filogenética para Escherichia coli. Aplicaciones: Ideal para estudios epidemiológicos. Características: Combina MLST e información específica de filogrupos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclinic', 'spa', 'clinic', 'Clínica', 'Una clínica médica, que puede utilizarse para proporcionar tratamiento, trabajo correctivo y/o instrucción.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclonalFrameML', 'spa', 'clonalFrameML', 'Software ClonalFrameML', 'Una herramienta de software de análisis de linaje o clado para reconstruir relaciones filogenéticas teniendo en cuenta la recombinación, utilizada en el análisis de linajes bacterianos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclostridiumGrp', 'spa', 'clostridiumGrp', 'Grupo Clostridium', 'Un grupo de medidas/métodos relacionados con las bacterias clostridium.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacloudy', 'spa', 'cloudy', 'Nublado', 'Categoría cualitativa para la medida meteorológica, que especifica un día nublado sin lluvia.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; github issue #124 and #204', NULL),
  ('spaclumpify', 'spa', 'clumpify', 'Clumpify de BBMap', 'Método de deduplicación que agrupa secuencias idénticas, utilizado a menudo para deduplicar lecturas de manera eficiente.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaclustalO', 'spa', 'clustalO', 'Clustal Omega', 'Software de secuenciación ampliamente utilizado para la alineación de múltiples secuencias y la producción de secuencias de consenso.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacm', 'spa', 'cm', 'Centímetros', 'Unidad de medida del sistema internacional de unidades (SI) equivalente a un centímetro.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaco', 'spa', 'co', 'Abreviatura de tabla de contactos', 'Abreviatura utilizada para referirse a la tabla que contiene información sobre un contacto, es decir, una persona que es el contacto de un sitio o laboratorio.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spaco2', 'spa', 'co2', 'Dióxido de carbono', 'Medida de la cantidad o concentración de dióxido de carbono.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; github issue #202', NULL),
  ('spacod', 'spa', 'cod', 'Demanda química de oxígeno', 'Demanda química de oxígeno.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spacol2Frdg', 'spa', 'col2Frdg', 'Tiempo de recolección a almacenamiento', 'El tiempo transcurrido entre la recogida de muestras y su colocación en un almacenamiento/refrigeración estable.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacolAMRGrp', 'spa', 'colAMRGrp', 'Grupo de resistencia antimicrobiana a colistina', 'El grupo de medidas y métodos relacionados con la resistencia antimicrobiana relacionada con la colistina.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spacolGrp', 'spa', 'colGrp', 'Grupo de recolección', 'Un grupo de atributos similares a mediciones relacionados con la recogida de muestras.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacolis', 'spa', 'colis', 'Resistencia a colistina', 'Bacterias resistentes a la colistina.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('spacollAppxSet', 'spa', 'collAppxSet', 'Conjunto de períodos de tiempo aproximados de recolección', 'El conjunto de entradas válidas para el campo de atributos collGenT.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacollAppxT', 'spa', 'collAppxT', 'Período de tiempo aproximado de recolección', 'El periodo de tiempo general (es decir, mañana, tarde, noche) de recogida de muestras.', 'Se utiliza cuando se desconoce la hora exacta.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacollDate', 'spa', 'collDate', 'Fecha de recolección (tiempo no incluido)', 'Fecha de recogida de la muestra, donde la hora se indica en un campo separado.', 'Solo se utiliza en combinación con el campo de periodo de tiempo aproximado de la recolección. De lo contrario, se debe informar la fecha y la hora juntas.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacollDT', 'spa', 'collDT', 'Fecha y hora de recolección', 'Para las muestras puntuales, se trata de la fecha, la hora y la zona horaria en que se tomó la muestra.', 'NA', '1.0.0', '2.0.0', 'Update in line with Github Issue #211', NULL),
  ('spacollDTEnd', 'spa', 'collDTEnd', 'Fecha y hora de finalización de recolección', 'Para las muestras integradas con promedio temporal, se trata de la fecha, la hora y la zona horaria en que se terminó de tomar la muestra.', 'NA', '1.0.0', '2.0.0', 'Update in line with Github Issue #211', NULL),
  ('spacollDTStart', 'spa', 'collDTStart', 'Fecha y hora de inicio de recolección', 'Para las muestras integradas con promedio temporal, se trata de la fecha, la hora y la zona horaria en que se comenzó a tomar la muestra.', 'NA', '1.0.0', '2.0.0', 'Update in line with Github Issue #211', NULL),
  ('spacollectSet', 'spa', 'collectSet', 'Conjunto de recolección de muestras', 'Métodos de recogida de muestras. ', 'Los métodos de recolección de muestras incluyen agua, aire y superficie. Véase el atributo «Conjunto de compartimentos» del método de recolección de muestras.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacollNum', 'spa', 'collNum', 'Número de recolección', 'Número de submuestras que se combinaron para crear la muestra. Utilice NA para el muestreo continuo, proporcional o pasivo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacollNumPer', 'spa', 'collNumPer', 'Período y número de recolección', 'Número de recolección compuesta.período.', '«Se trata de una medida compuesta que combina el «período de recolección» (collPer) y el «número de recolección» (collNum). El número y el período de recolección pueden utilizarse para reducir el número de encabezados de la tabla durante la recolección de datos. En el almacenamiento de datos, «collNum» y «collPeriod» deben transformarse en «collPer» y «collNum». Para muestras puntuales, muestras de superficie o muestras proporcionales al área, simplemente introduzca 1.   En el caso de muestras compuestas y proporcionales al flujo, introduzca el número de submuestras seguido de un punto y, a continuación, el periodo de muestreo en horas. Por ejemplo, para 4 submuestras compuestas que cubren un periodo de 8 horas, la entrada sería 4,2. Para 24 submuestras proporcionales al tiempo recogidas cada hora, la entrada sería 24,1. Para muestras proporcionales al volumen, la entrada para 24 submuestras recogidas durante 24 horas debería ser 24,24; en este caso, la parte del periodo de la entrada debe entenderse como el tiempo total de recogida en lugar de la periodicidad de la recogida. Para una bola COSCA o un hisopo Moore que recoge durante 24 horas, la entrada sería 1,24".', '2.0.0', '3.0.0', 'Depreciated as it really belongs in the widenames table, not parts.', NULL),
  ('spacollPer', 'spa', 'collPer', 'Período de recolección', 'Período de recolección. El período de tiempo durante el cual se recolectó la muestra, en horas. Alternativamente, utilice collectionStart y collectionEnd.', 'Ejemplos: 1 hora, 6 horas, 24 horas', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spacollType', 'spa', 'collType', 'Tipo de recolección de muestra', 'El tipo de recolección. ', 'NA', '1.0.0', '2.0.0', 'description wording', NULL),
  ('spacolocated', 'spa', 'colocated', 'relación de ubicación conjunta', 'Segunda muestra o muestras múltiples recolectadas  en o cerca (entre medio metro y un metro de distancia) de la misma ubicación de muestra seleccionada para determinar la variabilidad local de un analito determinado. Los resultados analíticos de las muestras co-ubicadas pueden utilizarse para evaluar la variación del sitio, pero solo en el área de muestreo inmediata. Las muestras tomadas en la misma ubicación pero utilizando diferentes medios (es decir, muestras de agua y aire, muestras de suelo y sedimentos) también se clasifican como muestras co-ubicadas.', 'NA', '2.0.0', '2.0.0', 'added in V2.0; GitHub issue #94', NULL),
  ('spacolumnNameDep', 'spa', 'columnNameDep', 'Nombre de columna obsoleto', 'Nombre de la columna', 'Depreciado en la versión 2 de ODM. Las tablas de consulta ahora se incorporan en partes y conjuntos.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('spacommFacOth', 'spa', 'commFacOth', 'Instalación comercial - no especificada', 'Especifica un tipo de sitio que es una instalación comercial/lugar de trabajo que no se captura ni se describe de otra manera en el conjunto de geotipos.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spacommunitLev', 'spa', 'communitLev', 'Vigilancia a nivel comunitario', 'La vigilancia se realiza a nivel de toda la comunidad.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacommunitor', 'spa', 'communitor', 'Triturador', 'Dispositivo mecánico que tritura los residuos sólidos de gran tamaño presentes en las aguas residuales en partículas más pequeñas para evitar obstrucciones.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spacomp', 'spa', 'comp', 'Muestra compuesta - archivo', 'Muestra compuesta, normalmente generada por un muestreador automático.', 'Está pensado para actualizar y asignar datos de archivo a la versión más reciente de ODM. Por lo general, los muestreadores automáticos realizan muestreos proporcionales al tiempo o al flujo, por lo que se deben utilizar esos métodos de recolección. Esto es solo para muestras compuestas/muestreadoras automáticas en las que aún no se han especificado estos detalles adicionales. Utilice collectionPeriod para describir cuántas horas se tomó la muestra y collectionNum para registrar el número de muestras.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spacomp3', 'spa', 'comp3', 'Muestra compuesta instantánea de 3', 'Muestra compuesta compuesta por tres muestras puntuales separadas.', 'NA', '1.0.0', '2.0.0', 'Use grab with collection number (collectNum) = 3', NULL),
  ('spacomp3dep', 'spa', 'comp3dep', 'Muestra compuesta instantánea de 3 obsoleto', 'Muestra compuesta compuesta por tres muestras puntuales separadas.', 'Obsoleto en la versión 2, no lo utilice.', '1.0.0', '2.0.0', 'depreciated, "default" entries are no longer in use.', NULL),
  ('spacomp3h', 'spa', 'comp3h', 'Muestra compuesta instantánea de 3 horas', 'Muestra compuesta de tres horas con tres muestras puntuales tomadas una vez por hora, generalmente de forma manual.', 'NA', '1.0.0', '2.0.0', 'Use grab with collection period (collectPer) = 3', NULL),
