  ('spad3g', 'spa', 'd3g', 'd3g gen diana de variante ómicron', 'd3g objetivo del gen de la mutación variante ómicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spad63g', 'spa', 'd63g', 'd63g gen diana de variante delta', 'd63g objetivo del gen de la mutación variante delta.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spad796y', 'spa', 'd796y', 'd796y gen diana de variante ómicron', 'd796y objetivo del gen de la mutación variante ómicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spad950n', 'spa', 'd950n', 'd950n gen diana de variante delta', 'd950n objetivo del gen de la mutación variante delta.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadada2', 'spa', 'dada2', 'DADA2', 'Aplicación de procesamiento de datos de secuenciación que se utiliza principalmente en la secuenciación de amplicones para la corrección de errores y la generación de variantes de secuencias de amplicones.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadaiCo', 'spa', 'daiCo', 'Recuento diario', 'Recuento diario de casos de una enfermedad determinada.', 'Agregación para una medida de población o enfermedad con el fin de explicar los efectos clínicos a nivel de población.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadatabase', 'spa', 'database', 'Clase de base de datos y repositorio de datos', 'Medidas y métodos relacionados con bases de datos y repositorios de datos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadataColl', 'spa', 'dataColl', 'Sector u organización de recolección de datos', 'Describe a las organizaciones que se dedican principalmente a recopilar, compilar, analizar y/o gestionar datos.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadataHost', 'spa', 'dataHost', 'Repositorio o banco de datos anfitrión', 'El repositorio externo o base de datos/banco en el que se almacena una secuencia (u otros datos externos).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadataRepoSet', 'spa', 'dataRepoSet', 'Conjunto de repositorios de datos', 'El conjunto mma para todas las categorías de entrada válidas para el campo dataRepo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadatasetDate', 'spa', 'datasetDate', 'Fecha de creación del conjunto de datos', 'Especifica la fecha en la que se creó un conjunto de datos determinado.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadatasetID', 'spa', 'datasetID', 'ID del conjunto de datos', 'El nombre del conjunto de datos que almacena información para MeasureReport, SampleReport y otras tablas de informes.', 'Siempre que sea posible, el nombre del conjunto de datos debe corresponder al custodio de datos original responsable de generar los datos medioambientales. (Sugerencia para una convención de nombres predeterminada).', '2.0.0', '3.0.0', 'removed as FK from the organizations, instruments tables.', NULL),
  ('spadatasets', 'spa', 'datasets', 'Tabla de conjunto de datos', 'Una tabla de informes para capturar detalles sobre el conjunto de datos parentales y los custodios de los datos. Proporciona la atribución de los recopiladores de datos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadatasetsOrder', 'spa', 'datasetsOrder', 'Orden de columnas de la tabla de conjuntos de datos', 'Especifica el orden de las columnas en una tabla de conjuntos de datos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadatasetsRequired', 'spa', 'datasetsRequired', 'Encabezados requeridos de la tabla de conjuntos de datos', 'Especifica las columnas necesarias en una tabla de conjuntos de datos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadataTypes', 'spa', 'dataTypes', 'Tipos de datos', 'El tipo de datos para una parte.', 'Los tipos de datos utilizados en el ODM incluyen: varchar, booleano, flotante, categoría, fecha, hora, fecha y hora, URL, correo electrónico. El tipo de datos corresponde a la entrada o celda dentro de una tabla de datos, más comúnmente dentro de una tabla de informe. Si la entrada de datos tiene una unidad, entonces el tipo de datos corresponde a la unidad y el tipo de datos se refiere a «unidad». Si la entrada de datos es una categoría, entonces el tipo de datos se refiere a «categoría». Todas las categorías son varchar. De lo contrario, el tipo de datos se identifica dentro de la entrada de la pieza. TBA: tipo de datos para el diccionario.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadate', 'spa', 'date', 'Tipo de datos de fecha', 'El tipo de datos para datos de fecha (no incluye la hora).', 'Solo se utiliza para las entradas del diccionario de piezas.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadateDep', 'spa', 'dateDep', 'Fecha', 'Fecha', 'Fecha en la que se creó o actualizó el método de ensayo (para la actualización de la versión).', '1.0.0', '3.0.0', 'Still depreciated, but partID updated to reflect that while avoiding colisions with the new date data type.', NULL),
  ('spadatetime', 'spa', 'datetime', 'Tipo de datos fecha-hora', 'El tipo de datos para datos de fecha y hora.', 'Solo se utiliza para las entradas del diccionario de piezas.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaday7Smooth', 'spa', 'day7Smooth', 'Suavizado de valores de 7 días', 'Este tratamiento de datos suaviza el valor de medición a lo largo de 7 días.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadays', 'spa', 'days', 'Días', 'Una unidad para indicar una duración en días.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaddbj', 'spa', 'ddbj', 'Banco de Datos de ADN de Japón (DDBJ)', 'Archivos del Banco de Datos de ADN de Japón (DDBJ).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaddcovE', 'spa', 'ddcovE', 'ddcov_e gen diana sars-cov-2', 'ddcov_e objetivo del gen de mutación sars-cov-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaddcovN', 'spa', 'ddcovN', 'ddcov_n gen diana sars-cov-2', 'ddcov_n objetivo del gen de mutación sars-cov-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaddpcr', 'spa', 'ddpcr', 'PCR digital en gotas (ddPCR)', 'Describe un análisis de PCR realizado utilizando tecnología de PCR con gotas digitales (general).', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadeath', 'spa', 'death', 'Muertes', 'Unidades para describir una medida poblacional de pacientes que han fallecido por una causa determinada.', 'Unidad para una medida de población o enfermedad para explicar los efectos clínicos a nivel de población.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadeconSeq', 'spa', 'deconSeq', 'DeconSeq', 'Software de deshosting que se utiliza para el deshosting mediante el filtrado de lecturas contra genomas de referencia del host.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadecontaMiner', 'spa', 'decontaMiner', 'DecontaMiner', 'Herramienta de control de calidad para secuenciar datos con el fin de detectar y eliminar la contaminación en conjuntos de datos NGS, especialmente útil en muestras clínicas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadecSurv', 'spa', 'decSurv', 'Vigilancia reducida', 'Reducción de las actividades de supervisión, a menudo debido a la disminución del riesgo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadedup', 'spa', 'dedup', 'Método de desduplicación', 'Método de secuenciación y deduplicación de PCR.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadedupSet', 'spa', 'dedupSet', 'Conjunto de métodos de desduplicación', 'Conjunto válido de entradas categóricas del método de deduplicación.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadeepARG', 'spa', 'deepARG', 'Software DeepARG', 'Herramienta de software que predice los genes AMR utilizando el aprendizaje profundo en datos metagenómicos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadehost', 'spa', 'dehost', 'Método de deshospedaje', 'Método de secuenciación y deshosting de PCR.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadehostSet', 'spa', 'dehostSet', 'Conjunto de métodos de deshospedaje', 'Conjunto válido de entradas categóricas del método de deshosting.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadel142144', 'spa', 'del142144', 'Deleción 142-144 de variante Ómicron', 'Variante Ómicron 142-144 Mutación por deleción', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadel143', 'spa', 'del143', 'deleción 143/145 gen diana de variante ómicron', '143 o 145 deleción variante Ómicron mutación gen objetivo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadel156157', 'spa', 'del156157', 'Deleción 156-157 de variante Delta', 'Mutación por deleción de la variante delta 156-157', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadel157', 'spa', 'del157', 'deleción 157/158 gen diana de variante delta', 'Gen objetivo de la mutación por deleción 157 o 158 de la variante delta.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadel2084', 'spa', 'del2084', 'deleción 2084/2084 gen diana de variante ómicron', 'Gen objetivo de la mutación por deleción 2084 o 2084 de la variante ómicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadel212', 'spa', 'del212', 'deleción 212/212 gen diana de variante ómicron', 'Gen objetivo de la mutación por deleción 212 o 212 de la variante ómicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadel3133', 'spa', 'del3133', 'Deleción 142-14431-33 de variante Ómicron', 'Mutación por deleción de la variante ómicron 142-14431-33.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadel3674', 'spa', 'del3674', 'deleción 3674/3676 gen diana de variante ómicron', '3674 o 3676 deleción del gen objetivo de la mutación de la variante Ómicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadel6970', 'spa', 'del6970', 'deleción 69/70 gen diana de variante ómicron', '69 o 70 deleción del gen objetivo de la mutación de la variante Ómicron.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadelayArriv', 'spa', 'delayArriv', 'Llegada retrasada o tránsito prolongado', 'Un retraso considerable (es decir, de más de 14 días) entre la recogida de la muestra y el inicio del análisis.', 'NA', '2.2.3', '2.2.3', 'added in v 2.2.3', NULL),
  ('spadelta', 'spa', 'delta', 'Delta', 'B.1.617.2', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadeltaGrp', 'spa', 'deltaGrp', 'Grupo de variante Delta del SARS-CoV-2', 'Un grupo de medidas/métodos relacionados con la variante Delta del SARS-CoV-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaden1', 'spa', 'den1', 'Virus del dengue tipo 1', 'Virus del dengue, tipo 1, medición general.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaden2', 'spa', 'den2', 'Virus del dengue tipo 2', 'Virus del dengue, tipo 2, medición general.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaden3', 'spa', 'den3', 'Virus del dengue tipo 3', 'Virus del dengue, tipo 3, medición general.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaden4', 'spa', 'den4', 'Virus del dengue tipo 4', 'Virus del dengue, tipo 4, medición general.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadenat', 'spa', 'denat', 'desnaturalización', 'Describe el ciclo de desnaturalización en un proceso de PCR.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadengue', 'spa', 'dengue', 'Dengue', 'Virus del dengue, medición general', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadepCovThresh', 'spa', 'depCovThresh', 'umbral de profundidad de cobertura', 'El umbral utilizado como límite para la profundidad de cobertura.', 'Proporcione el umbral de cobertura.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadepreciated', 'spa', 'depreciated', 'Obsoleto', 'Indicador que indica que una parte ya no se utiliza en el modelo. Véase partID = status', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaderived', 'spa', 'derived', 'Datos derivados', 'Datos derivados, datos que han sido objeto de agregación, estandarización, ajuste o cualquier tipo de limpieza antes de su presentación.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaderivedSamp', 'spa', 'derivedSamp', 'Muestra derivada', 'Una muestra derivada o elaborada a partir de otra muestra o material.', 'Una muestra derivada es un tipo de muestra creada mezclando material obtenido de una muestra de campo (por ejemplo, aguas residuales, suelo o aire) con aditivos adicionales en un entorno de laboratorio. Este proceso puede implicar la dilución de la muestra de campo original con agua limpia u otras soluciones, según sea necesario. Las muestras derivadas se utilizan normalmente para ajustar la concentración de la sustancia u organismo objetivo, haciéndola más adecuada para el análisis o para comprobar la eficacia y sensibilidad de los métodos de detección. En el ejemplo dado, una muestra derivada podría ser una submuestra de aguas residuales que se diluye con agua limpia para alcanzar una concentración específica, lo que permite un análisis más preciso y fiable.', '2.0.0', '3.0.0', 'partID changed from "derived" to "derivedSamp"', NULL),
  ('spadescr', 'spa', 'descr', 'Descripción', 'Descripción detallada de una medida, método o atributo.', 'Una descripción de la pieza que sirva para presentar claramente la pieza a un público amplio, incluido el personal técnico y no técnico. La descripción debe permitir a cualquier persona que genere datos de vigilancia medioambiental saber cómo identificar y registrar sus elementos de datos en el ODM. Se puede utilizar partReference para describir más detalladamente una pieza.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadescrChange', 'spa', 'descrChange', 'Descripción del cambio', 'Descripción del cambio en una parte con respecto a la versión anterior.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadesk', 'spa', 'desk', 'Escritorio o mostrador', 'Escritorio, mesa, encimera u otra superficie de trabajo plana.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadeso', 'spa', 'deso', 'Sólidos deshidratados', 'Sólidos deshidratados.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('spadet', 'spa', 'det', 'Detectado', 'Sustancia detectada o no detectada.', 'TRUE = detectado, FALSE = no detectado', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('spadetailsDep', 'spa', 'detailsDep', 'Acceso a detalles obsoleto', 'Más detalles sobre los requisitos de confidencialidad existentes de esta medición.', 'NA', '1.0.0', '2.0.0', 'depreciated, sharing moved to sharing schema', NULL),
  ('spadetLinClade', 'spa', 'detLinClade', 'Nombre de linaje o clado detectado', 'Medición para informar sobre la información detectada sobre el linaje o el clado, utilizada como «otra» para las mediciones que aún no se han capturado en la estructura ODM.', 'Más útil si se incluye en un conjunto de medidas con otras medidas relevantes.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadev', 'spa', 'dev', 'Variante desescalada', 'Una amenaza microbiana determinada se ha reducido; una variante reducida: diferentes instituciones pueden utilizar diferentes criterios para asignar este nivel de amenaza.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadevelopment', 'spa', 'development', 'Desarrollo', 'Indicador de que una parte está en fase de desarrollo. Véase partID = status', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadictionaryRefTableSet', 'spa', 'dictionaryRefTableSet', 'Conjunto de tablas de referencia de diccionario', 'Tablas de referencia o consulta.', 'Por ejemplo, la tabla de partes describe todos los elementos del ODM, incluyendo tablas, encabezados de tablas, medidas, métodos, categorías y unidades. Los conjuntos son colecciones de partes. Por ejemplo, las unidades se pueden agrupar en un unitSet. Los idiomas y las traducciones admiten traducciones.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadictionarySupport', 'spa', 'dictionarySupport', 'Hojas de diccionario adicionales', 'Hojas adicionales para la versión Excel del diccionario ODM.', 'Las hojas o pestañas del diccionario ODM Excel incluyen: todas las tablas ERD (tablas de consulta y tablas de entrada de datos) y tablas de apoyo adicionales. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadictSets', 'spa', 'dictSets', 'Tipo de conjunto de diccionario', 'Conjuntos utilizados para describir y agrupar tablas del diccionario.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadilFact', 'spa', 'dilFact', 'Factor de dilución', 'Especifica el grado de dilución de una muestra o alícuota antes del análisis.', 'El factor de dilución se indica como una medida sin unidades, donde un valor de 10 indica una dilución de 10:1.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadillute', 'spa', 'dillute', 'Diluciones puntuales', 'Concentración exacta o diluciones para generar una curva estándar.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadilution', 'spa', 'dilution', 'Clase de dilución', 'Medidas y métodos relacionados con las diluciones.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadiptheriaGrp', 'spa', 'diptheriaGrp', 'Grupo Difteria', 'Grupo de medidas/métodos relacionados con la bacteria de la difteria.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spadiscovar', 'spa', 'discovar', 'DISCOVAR de novo', 'Software de secuenciación que es un ensamblador optimizado para datos Illumina en la secuenciación del genoma completo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('spadisease', 'spa', 'disease', 'Clase de enfermedades (humanas)', 'Medidas y métodos relacionados con enfermedades o infecciones en humanos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadissGasUnitSet', 'spa', 'dissGasUnitSet', 'Conjunto de unidades de concentración de gas disuelto', 'Conjunto de unidades para medir las concentraciones de dióxido de carbono en el agua o el aire.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadissOxy', 'spa', 'dissOxy', 'Oxígeno disuelto', 'Medida del oxígeno disuelto en un medio líquido.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadna', 'spa', 'dna', 'Plantilla de ADN', 'La plantilla de ácido desoxirribonucleico (ADN) se utiliza para trabajos de PCR o secuenciación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spadnaFragLen', 'spa', 'dnaFragLen', 'Longitud de fragmento de ADN', 'Longitud del fragmento de ADN generado por corte mecánico o digestión enzimática con el fin de preparar una biblioteca.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadnaPrep', 'spa', 'dnaPrep', 'Kit de preparación de biblioteca Nextera DNA Flex/DNA Prep', 'Kit Nextera DNA Flex Library Prep, ahora llamado DNA Prep, de Illumina. Un kit flexible de preparación de bibliotecas basado en transposasa para una amplia gama de cantidades de ADN de entrada, adecuado para ADN microbiano y humano.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadnaRNAshield', 'spa', 'dnaRNAshield', 'Escudo DNA/RNA', 'Solución estabilizadora para ácidos nucleicos en muestras, incluidas las aguas residuales, que protege contra la degradación a temperatura ambiente.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadnc', 'spa', 'dnc', 'Datos no recopilados', 'Valor de datos faltantes cuando no se midieron o recopilaron datos; no se realizó un análisis, etc.', 'Indicador de valor faltante cuando el valor nunca se recopiló y debería faltar.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadnvE', 'spa', 'dnvE', 'Gen E del virus del dengue', 'Gen específico del dengue tipo 2.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadnvNS5', 'spa', 'dnvNS5', 'Gen NS5 del virus del dengue', 'Gen específico del dengue tipo 1.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadnvprM', 'spa', 'dnvprM', 'Gen prM del virus del dengue', 'Gen específico del dengue tipo 3 y 4.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spadoc', 'spa', 'doc', 'Profundidad de cobertura', 'El número medio de lecturas que representan un nucleótido determinado en la secuencia reconstruida, expresado como un valor de cobertura.', 'Se utiliza para interpretar la confianza en la presencia o la cantidad de una variante.', '2.0.0', '2.0.0', 'Issue #120', NULL),
