  ('spapopServ', 'spa', 'popServ', 'población atendida', 'Medida de un sitio que especifica la población de un sitio determinado o la población a la que presta servicio. ', 'NA', '2.0.0', '2.3.0', 'Updated to a measurement after being removed as a header in the sites table.', NULL),
  ('spapopServRange', 'spa', 'popServRange', 'intervalo de población atendida', 'Población a la que presta servicio un sitio, cuando se informa como un intervalo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapopulationUnitSet', 'spa', 'populationUnitSet', 'conjunto de unidades de población', 'Conjunto de unidades para mediciones relacionadas con hospitales.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spapor', 'spa', 'por', 'nombre corto de la tabla de relaciones de polígonos', 'Nombre abreviado utilizado para hacer referencia a la tabla en la que se registran las relaciones entre polígonos.', 'tabla', '2.3.0', '2.3.0', 'added in V2.3.0', NULL),
  ('spaporechop', 'spa', 'porechop', 'Porechop', 'Aplicación de procesamiento de datos secuenciales diseñada específicamente para el recorte de adaptadores en datos de Oxford Nanopore Technologies.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaport', 'spa', 'port', 'puerto o puerto marítimo', 'Un puerto es cualquier masa de agua protegida donde pueden atracar o fondear barcos o buques. Un puerto es una instalación construida alrededor de un puerto con instalaciones para la carga y descarga de dichos buques.', 'NA', '2.2.3', '2.2.3', 'added in v2.2.3', NULL),
  ('spapoSaSpecimenSet', 'spa', 'poSaSpecimenSet', 'conjunto de especímenes de población o muestras', 'Conjunto de muestras que incluye muestras de población o muestras de muestra.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaposCon', 'spa', 'posCon', '#N/A', '#N/A', '#N/A', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapoSiSpecimenSet', 'spa', 'poSiSpecimenSet', 'conjunto de especímenes de población o sitio', 'Conjunto de muestras que incluye muestras de población o muestras de sitio.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spapoSpecimenSet', 'spa', 'poSpecimenSet', 'conjunto de especímenes de población', 'Conjunto de muestras que incluye solo muestras de población.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spapostgreSQL', 'spa', 'postgreSQL', 'licencia PostgreSQL', 'La licencia para la medida o el conjunto de datos se gestiona bajo la licencia PostgreSQL.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapp', 'spa', 'pp', 'porcentaje de resultados positivos', 'Porcentaje positivo de las medidas de la muestra.', 'Se puede utilizar para hisopos Moore, etc.', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('spappm', 'spa', 'ppm', 'partes por millón (ppm)', 'Partes por millón.', 'NA', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('spappmv', 'spa', 'ppmv', 'PMMoV-CP', 'Región del gen de la proteína de la cápside del virus del moteado suave del pimiento', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spapprt', 'spa', 'pprt', 'tasa de positividad (%)', 'Porcentaje de positividad de las pruebas realizadas en un día en una región determinada.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('spapps', 'spa', 'pps', 'porcentaje de lodo primario', 'Porcentaje de sólidos totales, para lodos primarios.', 'NA', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('spappt', 'spa', 'ppt', 'partes por mil (‰)', 'Partes por mil.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapr', 'spa', 'pr', 'nombre corto de tabla de relaciones de protocolos', 'Nombre abreviado utilizado para hacer referencia a la tabla que contiene la información y los detalles organizativos (como el orden) sobre un protocolo determinado, registrados como una serie de pasos del protocolo (protocolSteps). ', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spaprec', 'spa', 'prec', 'precipitación (desde solución)', 'Formación de un sólido a partir de una sustancia disuelta en una solución, normalmente inducida por reacciones químicas o cambios de temperatura/pH.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaprecip', 'spa', 'precip', 'precipitación – general', 'Medida general de precipitación, tipo no especificado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaprecipitation', 'spa', 'precipitation', 'clase de precipitación', 'Medidas y métodos relacionados con la precipitación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprecipitationUnitSet', 'spa', 'precipitationUnitSet', 'conjunto de unidades de precipitación', 'Conjunto de unidades para mediciones de precipitación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spapreConcTemp', 'spa', 'preConcTemp', 'temperatura de almacenamiento antes de concentración', 'Temperatura a la que se almacenó una muestra entre su recogida y su concentración.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapreConcTime', 'spa', 'preConcTime', 'tiempo de almacenamiento antes de concentración', 'Tiempo durante el que se almacena una muestra entre su recogida y su concentración.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapredicted', 'spa', 'predicted', 'datos predichos', 'Datos previstos, datos generados por modelos o algoritmos predictivos, no tomados directamente de las mediciones de las muestras.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapredictiveModels', 'spa', 'predictiveModels', 'tipo de cálculo de modelado predictivo', 'Un enfoque estadístico o de aprendizaje automático utilizado para estimar valores o resultados futuros basándose en patrones de datos históricos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapreExtractTemp', 'spa', 'preExtractTemp', 'temperatura de almacenamiento antes de extracción', 'La temperatura a la que se almacenó una muestra entre la concentración y la extracción.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('spapreExtractTime', 'spa', 'preExtractTime', 'tiempo de almacenamiento antes de extracción', 'El tiempo durante el que se almacena una muestra entre la concentración y la extracción.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapreQC', 'spa', 'preQC', 'preQC (de Meraculous)', 'Una herramienta de control de calidad para datos de secuenciación que evalúa la calidad de los datos antes del ensamblaje, especialmente para genomas grandes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapresampAct', 'spa', 'presampAct', 'actividad de pre-muestreo', 'Una medida para registrar cualquier actividad relevante que se produzca antes de la fuente de muestreo. Por ejemplo, registrar que el río del que se toma la muestra atraviesa tierras de cultivo, o que se produjo filtración y/o sedimentación en la planta de tratamiento de aguas residuales antes de recoger la muestra.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapresampSet', 'spa', 'presampSet', 'conjunto de categorías de actividad de pre-muestreo', 'El conjunto de valores de entrada válidos para informar de la actividad previa al muestreo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapreSampWeath', 'spa', 'preSampWeath', 'condiciones meteorológicas pre-muestreo', 'El tiempo meteorológico previo al día del muestreo, sin incluir este.', 'El método de pretratamiento se puede describir utilizando un método. Véase methodID.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapretreat', 'spa', 'pretreat', 'pretratamiento', '¿Se trató químicamente la muestra de alguna manera con la adición de estabilizadores u otros', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('spaprimClar', 'spa', 'primClar', 'clarificador primario', 'Un gran tanque de sedimentación que elimina los sólidos y los materiales flotantes de las aguas residuales antes del tratamiento secundario.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaprimer', 'spa', 'primer', 'cebador genético', 'ID del método utilizado para indicar el cebador utilizado para un ensayo de PCR o secuenciación.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprimerSet', 'spa', 'primerSet', 'conjunto de cebadores genéticos', 'El conjunto de cebadores genéticos utilizados en ensayos de secuenciación o PCR.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprinseq', 'spa', 'prinseq', 'PRINSEQ', 'Una herramienta de canalización de control de calidad para datos de secuenciación que evalúa y filtra secuencias en función de la complejidad, las puntuaciones de calidad y el contenido de GC.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaprinseqLite', 'spa', 'prinseqLite', 'Prinseq‑lite', 'Una aplicación de procesamiento de datos de secuenciación que filtra las secuencias en función de su complejidad y elimina las lecturas de baja calidad.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapriv', 'spa', 'priv', 'sector privado', 'La categoría de tipo de organización utilizada para el sector privado o los grupos sin ánimo de lucro que no se incluyen en la categoría académica.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprivate', 'spa', 'private', 'datos privados – no para difusión', 'La medida o el conjunto de datos son datos privados, no destinados a su difusión.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapro', 'spa', 'pro', 'nombre corto de tabla de protocolos', 'El nombre abreviado utilizado para hacer referencia a la tabla que contiene la información resumida y los detalles sobre un protocolo determinado. ', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spaprocGrp', 'spa', 'procGrp', 'grupo de procesamiento', 'Un grupo de medidas/métodos relacionados con el procesamiento de muestras para su análisis.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprofil', 'spa', 'profil', 'encuesta o perfil ambiental', 'El objetivo del muestreo/medida es registrar las características y perfilar un entorno determinado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaprogramDescr', 'spa', 'programDescr', 'tablas de descripción del programa', 'Tablas utilizadas para describir los programas de vigilancia y pruebas.', 'Las tablas de descripción del programa registran metadatos sobre las organizaciones, ubicaciones y protocolos. La información incluye el nombre, la ubicación y otra información de contacto. Estas tablas suelen completarse una vez y solo se actualizan cuando cambia la información de contacto.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprokka', 'spa', 'prokka', 'Prokka (con integración de serotipado)', 'Prokka (con integración de serotipado) Aunque se trata principalmente de una herramienta de anotación, los resultados de Prokka pueden combinarse con bases de datos para identificar los serotipos de determinados patógenos bacterianos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaprokkaRoary', 'spa', 'prokkaRoary', 'canal Prokka + Roary (Nextflow)', 'Prokka + Roary Pipeline. Enfoque: Anotación del genoma (Prokka) con MLST e integración de serotipado a través de Roary. Aplicaciones: Amplia compatibilidad con patógenos bacterianos. Características: Facilita el análisis del genoma central MLST y de genes accesorios.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapromAuto', 'spa', 'promAuto', 'kit TNA automatizado Promega', 'Extracción de ácido nucleico realizada con el kit automatizado tna de Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spapromegaLVTNA', 'spa', 'promegaLVTNA', 'kit de captura TNA de gran volumen para aguas residuales (Promega)', 'Kit de captura tna para grandes volúmenes de aguas residuales de Promega', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapromHt', 'spa', 'promHt', 'kit HT TNA Promega', 'Extracción de ácido nucleico realizada con el kit ht tna de Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spapromManu', 'spa', 'promManu', 'kit TNA manual Promega', 'Extracción de ácido nucleico realizada con el kit manual TNA de Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spapromWW', 'spa', 'promWW', 'kit de captura TNA de gran volumen para aguas residuales (Promega)', 'Extracción de ácido nucleico realizada con el kit de captura TNA para grandes volúmenes de aguas residuales de Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('spaprop', 'spa', 'prop', 'proporción del total', 'Proporción como porcentaje del total.', 'NA', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('spapropV', 'spa', 'propV', 'proporción de variante en la muestra', 'Proporción de una variante como porcentaje del total de variantes.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('spaprotein', 'spa', 'protein', 'clase de proteínas', 'Medidas y métodos relacionados con las proteínas.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolID', 'spa', 'protocolID', 'ID de protocolo', 'Identificador único para un protocolo determinado.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolIDContainer', 'spa', 'protocolIDContainer', 'contenedor ID de protocolo', 'Identificador único para el protocolo y los pasos y otros protocolos que lo componen.', 'El contenedor de ID de protocolo se rellena con un ID de protocolo (partID = protocolID)', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolIDObj', 'spa', 'protocolIDObj', 'objeto ID de protocolo', 'El objeto de la relación entre un protocolo y otro protocolo o paso, dentro de un contenedor de ID de protocolo determinado.', 'Rellene este campo utilizando el ID del protocolo (partID = protocolID). Junto con `protocolIDSub` o `stepIDSub` y `relationshipID`, la relación del protocolo se define como: [protocolIDSubject o stepIDSubject]  [relationshipID] [protocolIDObject o stepIDObject]. Ejemplo: stepIDSubject  precede a protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolIDSub', 'spa', 'protocolIDSub', 'sujeto ID de protocolo', 'El sujeto de la relación entre un protocolo y otro protocolo o paso, dentro de un contenedor de ID de protocolo determinado.', 'Rellene este campo utilizando el ID del protocolo (partID = protocolID). Junto con `protocolIDObj` o `stepIDObj` y `relationshipID`, la fila de `protocolRelationships` debe indicar: [protocolIDSubject o stepIDSubject]  [relationshipID] [protocolIDObject o stepIDObject]. Ejemplo: stepIDSubject  precede a protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolRelationships', 'spa', 'protocolRelationships', 'tabla de relaciones de protocolos', 'La tabla que contiene la información organizativa y los detalles (como el orden) sobre un protocolo determinado, registrados como una serie de pasos del protocolo (protocolSteps). ', 'Los protocolos son un grupo de pasos de protocolo relacionados. Por ejemplo, un paso de protocolo puede describir una concentración de muestra, una extracción, una inhibición o una medición. Los protocolos pueden incluir tanto methodID (un procedimiento) como measureIDs (una medida). Un ejemplo de método es la centrifugación, donde la velocidad de rotación de la centrifugación se describe como una medida.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolRelationshipsID', 'spa', 'protocolRelationshipsID', 'ID sintético para tabla protocolRelationships', 'Un ID único y autoincremental generado para producir un identificador único y una clave principal para cada fila de la tabla protocolRelationships.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spaprotocolRelationshipsOrder', 'spa', 'protocolRelationshipsOrder', 'orden de columnas de la tabla de relaciones de protocolos', 'Especifica el orden de las columnas en la tabla Organización del protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolRelationshipsRequired', 'spa', 'protocolRelationshipsRequired', 'encabezados obligatorios de la tabla de relaciones de protocolos', 'Especifica las columnas necesarias en la tabla Organización del protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolRelSet', 'spa', 'protocolRelSet', 'conjunto de relaciones de protocolos', 'Conjunto de valores válidos de relationshipID en la tabla protocolRelationships.', 'Utilizar solo para la relación de la tabla protocolRelationships relationshipID.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocols', 'spa', 'protocols', 'tabla de protocolos', 'La tabla para los protocolos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolsOrder', 'spa', 'protocolsOrder', 'orden de columnas de tabla de protocolos', 'Especifica el orden de las columnas en la tabla Protocolos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolsRequired', 'spa', 'protocolsRequired', 'encabezados obligatorios de tabla de protocolos', 'Especifica las columnas necesarias en la tabla Protocolos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolSteps', 'spa', 'protocolSteps', 'tabla de pasos de protocolo', 'La tabla para recopilar metadatos sobre pasos individuales en un protocolo, proceso metodológico o ensayo.', 'NA', '1.0.0', '2.0.0', 'updated from assay method into 2 tables, restructured.', NULL),
  ('spaprotocolStepsOrder', 'spa', 'protocolStepsOrder', 'orden de columnas de pasos de protocolo', 'Especifica el orden de las columnas en una tabla Pasos del protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolStepsRequired', 'spa', 'protocolStepsRequired', 'encabezados obligatorios de pasos de protocolo', 'Especifica las columnas necesarias en una tabla Pasos del protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolTableSet', 'spa', 'protocolTableSet', 'conjunto de tabla de protocolos', 'Tablas que contienen información sobre los métodos utilizados para la recogida o medición de muestras.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprotocolVersion', 'spa', 'protocolVersion', 'versión de protocolo', 'Especifica la versión de un conjunto de métodos.', 'Versión del conjunto de métodos. Se recomienda el uso de versiones semánticas.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprovHA', 'spa', 'provHA', 'acceso a proveedor HA (?), prov ha', 'Si es «no», estos datos no estarán disponibles para las autoridades sanitarias provinciales. Si falta, los datos estarán disponibles para las autoridades sanitarias provinciales.', 'NA', '1.0.0', '2.0.0', 'depreciated, sharing moved to sharing schema.', NULL),
  ('spaprovisional', 'spa', 'provisional', 'reporte provisional', 'Un informe provisional o intermedio.', 'Utilizar para mediciones que aún no se han finalizado. Normalmente, este propósito no se comunica públicamente. ', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spaprovLevel', 'spa', 'provLevel', 'Agregación a nivel de provincia en el sitio', 'Especifica que una cuenca/sitio representa un estado, provincia o región subnacional.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaps', 'spa', 'ps', 'nombre corto tabla de pasos de protocolo', 'El nombre abreviado que se utiliza para hacer referencia a la tabla para recopilar metadatos sobre pasos individuales en un protocolo, proceso metodológico o ensayo.', 'tabla', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('spapseudomonas', 'spa', 'pseudomonas', 'Pseudomonas', 'Pseudomonas', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapseudomonasGrp', 'spa', 'pseudomonasGrp', 'grupo Pseudomonas', 'Un grupo de medidas/métodos relacionados con la bacteria pseudomonas.', 'Se utiliza para describir la información del organismo para medidas generales.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('spapSludge', 'spa', 'pSludge', 'lodo del clarificador primario', 'Lodos producidos por los clarificadores primarios', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('spapStat', 'spa', 'pStat', 'estación de bombeo', 'Estación de bombeo', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('spapstGrit', 'spa', 'pstGrit', 'post-grit (post-desarenado)', 'Aguas residuales sin tratar después de las obras de cabecera de una planta de tratamiento (después de la eliminación de arena o de sólidos grandes en una planta de tratamiento, pero antes del clarificador primario)', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('spapsu', 'spa', 'psu', 'unidad práctica de salinidad (PSU)', 'Unidad práctica de salinidad (PSU)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spaptDescDep', 'spa', 'ptDescDep', 'descripción de pretratamiento (obsoleto)', 'Si se trata de un pretratamiento, describa el tratamiento que se realizó.', 'Obsoleto en la versión 2, no utilizar. Utilizar methodID de pretratamiento y especificar más detalles en el resumen y/o las notas, si es necesario.', '1.0.0', '2.0.0', 'depreciated, absorbed into more general "description" part', NULL),
  ('spaptot', 'spa', 'ptot', 'número de pruebas positivas', 'Número de pruebas positivas realizadas en un día en una región determinada.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('spapubAdm', 'spa', 'pubAdm', 'administración pública', 'Tipo de organización que describe las organizaciones gubernamentales que gestionan o administran programas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapubAuth', 'spa', 'pubAuth', 'autoridad pública', 'Tipo de organización que describe un organismo público con autoridad sobre un ámbito determinado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spapubHealth', 'spa', 'pubHealth', 'agencia de salud pública', 'Organismo de salud pública.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('spapublic', 'spa', 'public', 'acceso público', 'Si la respuesta es «no», estos datos no estarán disponibles para el público. Si falta, los datos estarán disponibles para el público.', 'NA', '1.0.0', '2.0.0', 'depreciated, sharing moved to sharing schema.', NULL),
