  ('spasra', 'spa', 'sra', 'Archivo de lectura de secuencias (SRA)', 'Archivo de secuencias leídas (SRA).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('spasrst2', 'spa', 'srst2', 'Software SRST2', 'Herramienta de software para analizar la resistencia a los antimicrobianos utilizando secuencias de lectura cortas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
