  ('poraDateEnd', 'por', 'aDateEnd', 'Fim da data da análise', 'Data em que a medição ou análise foi concluída.', 'NA', '1.0.0', '2.0.0', 'Depreciated. See issue #211. https://github.com/Big-Life-Lab/PHES-ODM/issues/211', NULL),
  ('poraDateStart', 'por', 'aDateStart', 'Início da data da análise', 'Data em que a medição ou análise foi iniciada.', 'NA', '1.0.0', '2.0.0', 'NA', NULL),
  ('poraddL1', 'por', 'addL1', 'Linha de endereço 1', 'Linha 1 (nome da rua, número e direção) para um determinado endereço.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraddL2', 'por', 'addL2', 'Linha de endereço 2', 'Linha 2 (número da unidade) para um determinado endereço.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraddresses', 'por', 'addresses', 'Tabela de endereços', 'A tabela que contém informações sobre endereços. Endereços podem ser registrados para locais, organizações ou contatos (indivíduos).', 'As tabelas Locais, Organizações e Contatos incluem um link para a tabela de endereços por meio do ID do Endereço.', '2.0.0', '2.0.0', 'NA', NULL),
  ('poraddressesOrder', 'por', 'addressesOrder', 'Ordem das colunas da tabela de endereços', 'Especifica a ordem das colunas na tabela Endereços.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraddressesRequired', 'por', 'addressesRequired', 'Cabeçalhos obrigatórios da tabela de endereços', 'Especifica as colunas necessárias em uma tabela Endereços.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraddressID', 'por', 'addressID', 'ID do endereço', 'Um identificador exclusivo para um endereço.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poradenovirusF40', 'por', 'adenovirusF40', 'Adenovírus (F40/41)', 'Adenovírus (F40/41)', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poradenovirusGrp', 'por', 'adenovirusGrp', 'Grupo Adenovírus', 'Um grupo de medidas/métodos relacionados a Adenovírus.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poradmRegLevel', 'por', 'admRegLevel', 'Regiões administrativas', 'Regiões administrativas', 'NA', '2.0.0', '3.0.0', 'Reactivated as organization level and sector categorical inputs, rather than attributes.', NULL),
  ('poradv40', 'por', 'adv40', 'Adenovírus 40', 'Sorotipo 40 do adenovírus.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('poradv41', 'por', 'adv41', 'Adenovírus 41', 'Sorotipo 41 do adenovírus.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('poradvF41Fibre', 'por', 'advF41Fibre', 'Adenovírus F41 Alvo do gene da fibra', 'Alvo do gene da fibra do grupo F41 do adenovírus humano', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('poraerTank', 'por', 'aerTank', 'Tanque de aeração', 'Uma câmara no tratamento de águas residuais onde o ar é introduzido para promover a decomposição microbiana de poluentes orgânicos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porafl30', 'por', 'afl30', 'Licença Acadêmica Livre v3.0', 'O licenciamento para a medida ou conjunto de dados é gerenciado sob a Licença Acadêmica Livre v3.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poraft', 'por', 'aft', 'Tarde', 'A amostra foi coletada à tarde, algum tempo após o almoço.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porafterQC', 'por', 'afterQC', 'Pós-QC', 'Uma ferramenta automatizada de controle de qualidade para dados FASTQ, combinando avaliação de qualidade e correção de erros.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porafu', 'por', 'afu', 'Filtro de ar', 'Filtro de ar como parte da unidade de filtração ou circulação.', 'Normalmente, a unidade teria um ventilador ou soprador.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraggragationScale', 'por', 'aggragationScale', 'Escala de agregação', 'Uma balança usada para uma agregação. Aplicável somente para medidas e unidades.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraggregation', 'por', 'aggregation', 'Agregação', 'Medidas estatísticas usadas para relatar uma medida. Cada agregação possui um valor correspondente.', 'A agregação padrão é `single`, que corresponde a uma única medição.', '1.0.0', '2.0.0', 'restructured', NULL),
  ('poraggregationInput', 'por', 'aggregationInput', 'Entrada de agregação (tabela ampla)', 'O partID da agregação usada em um nome amplo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poraggregationName', 'por', 'aggregationName', 'Nome da agregação (tabela ampla)', 'A agregação referenciada para o nome amplo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poraggregations', 'por', 'aggregations', 'Agregações', 'Medidas estatísticas usadas para relatar uma medida. Cada medida relatada como um número deve ser relatada com uma agregação.', 'A agregação padrão é `single`, que corresponde a uma única medição.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraggregationScales', 'por', 'aggregationScales', 'Escalas de agregação', 'A escala de um conjunto de agregação. As escalas de agregação incluem quantitativa e qualitativa.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraggregationSet', 'por', 'aggregationSet', 'Conjunto de agregação', 'O conjunto de agregação para uma unidade.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraggregationSets', 'por', 'aggregationSets', 'Conjuntos de agregação', 'Conjuntos de agregações.', 'Exemplos de conjuntos de agregação incluem logaritmo, linear e booleano.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poragpl30', 'por', 'agpl30', 'Licença Pública Geral GNU Affero v3.0', 'O licenciamento da medida ou conjunto de dados é gerenciado pela GNU Affero General Public License v3.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poragri', 'por', 'agri', 'Atividade agrícola', 'A atividade agrícola ocorreu a montante do local de amostragem.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poragt', 'por', 'agt', 'Teste de gradiente antimicrobiano', 'Um teste de gradiente em tira é realizado de acordo com as instruções do fabricante: uma pequena tira de plástico ou papel impregnada com antibiótico é colocada sobre ágar inoculado. Na placa de Petri padronizada de 100 mm, duas tiras podem ser colocadas, enquanto na placa de Petri maior de 150 mm, até seis antibióticos podem ser testados simultaneamente.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porair', 'por', 'air', 'Compartimento de ar', 'Uma medida ou observação feita a partir de uma substância no ar.', 'NA', '2.0.0', '2.0.0', 'added in V2.0, changed to partType = compartment', NULL),
  ('porairCompartmentSet', 'por', 'airCompartmentSet', 'Conjunto de compartimentos de ar', 'Um conjunto de compartimentos para medidas e métodos no compartimento de ar.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porairpln', 'por', 'airpln', 'Avião', 'Tipo de categoria de galpão de amostras de aeronaves', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('porairport', 'por', 'airport', 'Aeroporto', 'Tipo de categoria de galpão de amostras de aeroportos', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porairportLists', 'por', 'airportLists', 'Planilha de listas de aeroportos', 'Listas de peças usadas para gerar modelos de entrada de dados para aeroportos e aeronaves.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porairportSheetSet', 'por', 'airportSheetSet', 'Conjunto de planilhas de aeroportos', 'Planilhas no modelo completo de vigilância aeroportuária (lista + modelo).', '`ODM_template-planes_{version}.xlxs', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porairportTemplate', 'por', 'airportTemplate', 'Modelo de vigilância de aeroportos', 'O modelo de entrada para vigilância aeroportuária e de aeronaves na UE.', 'NA', '2.0.0', '2.1.0', 'Update', NULL),
  ('porairSurfaceCompartmentSet', 'por', 'airSurfaceCompartmentSet', 'Conjunto de compartimentos de ar e superfície', 'Um conjunto de compartimentos para medidas e métodos nos compartimentos de ar ou superfície.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porairTemp', 'por', 'airTemp', 'Temperatura ambiental', 'Temperatura ambiente.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('porairWaterCompartmentSet', 'por', 'airWaterCompartmentSet', 'Conjunto de compartimentos de ar e água', 'Um conjunto de compartimentos para medidas e métodos nos compartimentos de ar ou água.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poraliasDep', 'por', 'aliasDep', 'Alias depreciado', 'ID de um ensaio que é o mesmo ou similar. Uma lista separada por vírgulas.', 'Descontinuado a partir da versão 2, evite o uso. Use notas em vez disso.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('poraliasIDDep', 'por', 'aliasIDDep', 'ID de alias depreciado', 'ID do alias', 'ID de um ensaio que seja igual ou semelhante. Uma lista separada por vírgulas.', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('poraliView', 'por', 'aliView', 'AliView', 'Software de sequenciamento que é um editor de alinhamento amigável com opções de sequência de consenso.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
