INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('poralkalinitySet', 'por', 'alkalinitySet', 'Conjunto de unidades de alcalinidade', 'Conjunto de unidades para medições de alcalinidade.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porallActionsSet', 'por', 'allActionsSet', 'Conjunto de todas as ações de saúde pública', 'Um conjunto de todas as categorias válidas para ações de saúde pública, independentemente do tipo de ação.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porallDo', 'por', 'allDo', 'Todos os domínios', 'Domínio que especifica que pode ser aplicado a todos os domínios: biológico, químico e físico.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porallele', 'por', 'allele', 'Classe de alelos', 'Medidas e métodos relacionados a alelos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poralleleUnitSet', 'por', 'alleleUnitSet', 'Conjunto de unidades de alelos', 'Conjunto de unidades para alelos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porallOrgs', 'por', 'allOrgs', 'Acesso a todas as organizações', 'Se a resposta for "não", esses dados não estarão disponíveis para nenhuma organização parceira. Se ausente, os dados estarão disponíveis para todas as organizações.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('porallpathsLG', 'por', 'allpathsLG', 'AllPaths-LG', 'Um software de sequenciamento projetado para montagens de alta qualidade usando dados Illumina grandes e pareados.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porallStandardSet', 'por', 'allStandardSet', 'Conjunto de valores padrão de ajuste de dados', 'Conjunto de valores de entrada válidos para o campo padrão.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poralod', 'por', 'alod', 'Limite de detecção do ensaio (LOD)', 'O nível mínimo de um alvo consistentemente detectável (por exemplo, com 95% de probabilidade) usando o ensaio, considerando apenas as etapas de amplificação e quantificação de RT-qPCR.', 'NA', '2.2.0', '3.0.0', 'changed quality indicator set from general to measure.', NULL),
  ('poraloh3', 'por', 'aloh3', 'Precipitação Aloh3', 'Precipitação de Aloh3', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('porambigNs', 'por', 'ambigNs', 'Número de bases ambíguas (Ns) normalizadas', 'O número de bases ambíguas (Ns) normalizadas por 100 quilopares de bases (kbp).', 'Forneça um valor numérico (não é necessário incluir unidades).', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poramDefDep', 'por', 'amDefDep', 'ID do método de ensaio padrão depreciado', 'Usado como padrão quando uma nova medição é criada para este laboratório. Consulte o ID na tabela Método de Ensaio.', 'Descontinuado a partir da versão 2, evite o uso. Especifique o tipo ou entre em contato com a equipe de pesquisa do PHES-ODM para adicionar seu item específico por meio de uma issue no GitHub (https://github.com/Big-Life-Lab/PHES-ODM/issues) ou pelo e-mail phesd_odm@ohri.ca', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('poramiconUf', 'por', 'amiconUf', 'Ultrafiltração Amicon', 'Ultrafiltração de amplicon', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('poramiMP96', 'por', 'amiMP96', 'Filtro Amicon, extrair com MP96', 'Extração de ácido nucleico, geralmente usada para a fração líquida de uma amostra de águas residuais, usando filtração de amplicon e um MP96 para extração final.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poramp', 'por', 'amp', 'Sequenciamento de amplicons', 'Especifica a estratégia de amplicon para sequenciamento genético.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porampliArtifact', 'por', 'ampliArtifact', 'Artefatos de amplificação de sequência', 'Artefatos de amplificação de sequência detectados.', 'NA', '2.3.0', '2.3.0', 'added in v 2.3.0', NULL),
  ('porampSize', 'por', 'ampSize', 'Tamanho do amplicon', 'O comprimento do amplicon gerado pela amplificação por PCR.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poramrClass', 'por', 'amrClass', 'Classificação de resistência antimicrobiana (AMR)', 'Um tipo de ação de saúde pública em que a classificação do nível de ameaça foi realizada em uma cepa de micróbios resistentes a antimicrobianos (RAM) e comunicada ao público.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poramrClassSet', 'por', 'amrClassSet', 'Conjunto de valores de classificação de resistência antimicrobiana (AMR)', 'Um conjunto de categorias válidas para o campo de ação de saúde pública, em que o tipo de ação é "classificação de resistência a antimicrobianos (RAM)".', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poramrFinderPlus', 'por', 'amrFinderPlus', 'Software AMRFinderPlus', 'Ferramenta de software desenvolvida pelo NCBI para detectar genes de RAM em genomas bacterianos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poramrGrp', 'por', 'amrGrp', 'Grupo de resistência antimicrobiana', 'O grupo para medidas e métodos relativos a micróbios resistentes a antimicrobianos (geral).', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('poramrSoft', 'por', 'amrSoft', 'Software de análise AMR', 'Uso de software para analisar genomas e genes bacterianos para resistência a antimicrobianos (RAM).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poramrSoftSet', 'por', 'amrSoftSet', 'Conjunto de software AMR', 'O conjunto válido de categorias de software de análise de RAM.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('poranaplasmaGrp', 'por', 'anaplasmaGrp', 'Grupo Anaplasma', 'Um grupo de medidas/métodos relacionados a bactérias anaplasma.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porandBoo', 'por', 'andBoo', 'Agregação booleana AND', 'Agregação "AND".', 'Se todos os valores na agregação forem "TRUE", a agregação AND também será "TRUE". Se todos os valores na agregação forem "FALSE", a agregação AND também será "TRUE".', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poranneal', 'por', 'anneal', 'Recozimento/extensão', 'Descreve o ciclo de anelamento e/ou extensão em um processo de PCR.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poranyCompartmentSet', 'por', 'anyCompartmentSet', 'Qualquer conjunto de compartimentos', 'Um conjunto de compartimentos para medidas e métodos em qualquer compartimento.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poranySpecimenSet', 'por', 'anySpecimenSet', 'Qualquer conjunto de amostras', 'Um conjunto de espécimes que inclui qualquer espécime.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porapache20', 'por', 'apache20', 'Licença Apache 2.0', 'O licenciamento para a medida ou conjunto de dados é gerenciado sob a licença Apache 2.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poraPhagocytophilum', 'por', 'aPhagocytophilum', 'Anaplasma phagocytophilum', 'Anaplasma phagocytophilum', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
