  ('pordel143', 'por', 'del143', 'del143/145', 'Alvo genético da mutação da variante Ômicron com deleção 143 ou 145.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordel156157', 'por', 'del156157', 'Deleção da variante Delta 156-157', 'Mutação por deleção da variante Delta 156-157', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('pordel157', 'por', 'del157', 'del 157/158', 'Alvo genético da mutação da variante Delta 157 ou 158.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordel2084', 'por', 'del2084', 'del2084/2084', 'Alvo genético da mutação da variante Ômicron com deleção 2084 ou 2084.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordel212', 'por', 'del212', 'del212/212', 'Alvo genético da mutação da variante Ômicron com deleção 212 ou 212.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordel3133', 'por', 'del3133', 'Deleção da variante Omicron 142-14431-33', 'Mutação por deleção da variante Ômicron 142-14431-33.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('pordel3674', 'por', 'del3674', 'del3674/3676', '3674 ou 3676 gene alvo de mutação da variante ômicron com deleção.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordel6970', 'por', 'del6970', 'del69/70', '69 ou 70 gene alvo de mutação da variante ômicron com deleção.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordelayArriv', 'por', 'delayArriv', 'Chegada atrasada ou trânsito prolongado', 'Um atraso substancial (ou seja, superior a 14 dias) entre a coleta da amostra e o início da análise.', 'NA', '2.2.3', '2.2.3', 'added in v 2.2.3', NULL),
  ('pordelta', 'por', 'delta', 'Delta', 'B.1.617.2', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pordeltaGrp', 'por', 'deltaGrp', 'Grupo da variante Delta do SARS-CoV-2', 'Um grupo de medidas/métodos relacionados à Variante Delta do SARS-CoV-2.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porden1', 'por', 'den1', 'Vírus da dengue tipo 1', 'Vírus da dengue, Tipo 1, medição geral', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porden2', 'por', 'den2', 'Vírus da dengue tipo 2', 'Vírus da dengue, Tipo 2, medição geral', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
