  ('porecl20', 'por', 'ecl20', 'Licença Comunitária Educacional v2.0', 'O licenciamento para a medida ou conjunto de dados é gerenciado pela Licença de Comunidade Educacional v2.0.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porecoli', 'por', 'ecoli', 'Escherichia coli', 'Concentração de bactérias que são transmitidas pelas fezes de humanos, animais de criação e animais selvagens', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porecoliGrp', 'por', 'ecoliGrp', 'Grupo Escherichia coli', 'Um grupo de medidas/métodos relacionados à bactéria Escherichia coli.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
