  ('poreducation', 'por', 'education', 'Educação', 'Uma medida ou amostra coletada para fins educacionais ou de treinamento.', 'Use este propósito, por exemplo, ao ensinar como usar o PHES-ODM.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porefficient', 'por', 'efficient', 'Eficiência', 'A eficiência relatada para uma curva padrão.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poreffluNS', 'por', 'effluNS', 'Efluente de águas residuais - não especificado', 'O material da amostra é efluente de águas residuais - se primário, secundário ou outro, não é especificado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
