  ('pormeOthDe', 'por', 'meOthDe', 'Descrição de outra medida', 'Descrição de outra medida (measOtherDesc).', 'NA', '1.0.0', '2.0.0', 'Depreciated in version 2 with all "other" fields', NULL),
  ('pormeqL', 'por', 'meqL', 'Miliequivalente por litro', 'Unidade de alcalinidade, miliequivalentes por litro.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('pormes', 'por', 'mes', 'Medidas Tipo de parte abreviada', 'O nome abreviado usado para referenciar o tipo de medida. Todas as medidas têm `partType` = "measurements".', 'tipo de peça', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('pormESV', 'por', 'mESV', 'Tamanho/volume efetivo da amostra', 'Tamanho/Volume Efetivo da Amostra (VSE) é a quantidade do tamanho/volume da amostra original que foi realmente analisada em uma reação de qPCR (consulte o Quadro 2.1 Protocolo).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('pormet', 'por', 'met', 'Métodos Tipo de parte abreviada', 'O nome abreviado usado para referenciar os procedimentos ou etapas para coleta de amostras ou execução de medidas.', 'tipo de peça', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('pormetaboliteGrp', 'por', 'metaboliteGrp', 'Grupo de metabólitos', 'Um grupo de medidas/métodos relacionados a metabólitos.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('pormetAMOS', 'por', 'metAMOS', 'MetAMOS', 'Um software de sequenciamento que é um pipeline automatizado para montagem e anotação metagenômica.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('pormetaPhIAn', 'por', 'metaPhIAn', 'Software MetaPhlAn', 'Ferramenta de software que cria perfis de comunidades microbianas e pode fornecer insights sobre genes de resistência.', 'Também usado para desduplicação.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
