  ('pormethod', 'por', 'method', 'Método', 'Um procedimento para coletar uma amostra ou realizar uma medição.', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pormethodConc', 'por', 'methodConc', 'Método de concentração', 'Descrição do método para concentrar uma amostra de águas residuais.', 'Descrição do método usado para concentrar a amostra', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pormethodConcSet', 'por', 'methodConcSet', 'Conjunto de métodos de concentração', 'Um conjunto de métodos de concentração.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pormethodInput', 'por', 'methodInput', 'Entrada do método (tabela ampla)', 'O partID do método usado em um nome amplo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('pormethodName', 'por', 'methodName', 'Nome do método (amplo tabela)', 'O método referenciado para o nome amplo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('pormethods', 'por', 'methods', 'Métodos', 'Procedimentos ou etapas para coletar amostras ou realizar medições.', 'Por exemplo, `methodExtract` é um método que descreve como uma amostra foi extraída.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pormfAcidmgcl2', 'por', 'mfAcidmgcl2', 'Filtração por membrana com acidificação e mgcl2', 'Filtração por membrana com acidificação e mgcl2', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('pormfAcidmgcl2SS', 'por', 'mfAcidmgcl2SS', 'Filtração por membrana com acidificação e mgcl2, membrana recombinada com sólidos separados', 'Filtragem por membrana com acidificação e mgcl2, membrana recombinada com sólidos separados', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
