  ('porpooled', 'por', 'pooled', 'Agrupado', 'Esta é uma amostra agrupada e, portanto, composta por várias amostras secundárias obtidas em diferentes sítios?', 'NA', '1.0.0', '2.0.0', 'added in V2.0.0', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('porpop', 'por', 'pop', 'População', 'Uma medida ou observação para uma área geográfica ou população.', 'Os exemplos incluem medidas de compartimento humano, como números de casos, taxas de hospitalização por doenças, ou medidas de compartimento de superfície ou ar, como cobertura de neve ou temperatura ambiente.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porpopAreaSet', 'por', 'popAreaSet', 'Conjunto de tipos de área povoada', 'Conjunto de valores válidos usados para descrever o tipo de uma área povoada.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopAreaType', 'por', 'popAreaType', 'Tipo de área povoada', 'Tipo de área povoada amostrada (ex.: urbana, rural)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopAs', 'por', 'popAs', 'Método de avaliação populacional', 'Método para avaliar a contagem populacional de um local/polígono.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopClass', 'por', 'popClass', 'Classe populacional', 'Medidas e métodos relacionados à população (ex.: Medidas de população, localização).', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopDateTypeDep', 'por', 'popDateTypeDep', 'Tipo de data para relato de caso depreciado', 'Tipo de data usada para casos confirmados. Normalmente, o relatório ou episódio é relatado. As datas de início e teste geralmente não são relatadas nos dados agregados.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('porpopDensity', 'por', 'popDensity', 'Densidade populacional', 'Medida da densidade populacional de um local.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopDensUnitSet', 'por', 'popDensUnitSet', 'Conjunto de unidades de densidade populacional', 'Conjunto de unidades para medidas de densidade populacional de um local.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopEq', 'por', 'popEq', 'Equivalentes populacionais', 'Uma unidade para medir a capacidade de projeto de estações de tratamento de águas residuais, representada como a quantidade aproximada de água que uma pessoa usaria.', 'NA', '1.0.0', '2.0.0', 'description wording, structure; github issue #123', NULL),
  ('porpopGrp', 'por', 'popGrp', 'Grupo populacional', 'Um grupo de medidas/métodos relacionados a fatores em nível populacional.', 'Exemplos podem ser números de casos, taxas de hospitalização, etc.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porpopIntSet', 'por', 'popIntSet', 'Conjunto de intervalos populacionais', 'A coleção de entradas categóricas para medidas de intervalo populacional.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopMetSet', 'por', 'popMetSet', 'Conjunto de métodos de avaliação populacional', 'O conjunto de entradas válidas para o método de avaliação populacional.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpoPolySpecimenSet', 'por', 'poPolySpecimenSet', 'Conjunto de espécimes de população ou polígono', 'Um conjunto de espécimes que inclui espécimes populacionais ou poligonais.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopServ', 'por', 'popServ', 'População atendida', 'Uma medida de um local, que especifica a população de/população atendida por um determinado local.', 'NA', '2.0.0', '2.3.0', 'Updated to a measurement after being removed as a header in the sites table.', NULL),
  ('porpopServRange', 'por', 'popServRange', 'População atendida - Intervalo', 'População atendida por um local, quando relatada como um intervalo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpopulationUnitSet', 'por', 'populationUnitSet', 'Conjunto de unidades populacionais', 'Conjunto de unidades para medições relacionadas a hospitais.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porpor', 'por', 'por', 'Tabela de relacionamentos de polígonos Nome abreviado', 'O nome abreviado usado para referenciar a tabela para registrar as relações entre polígonos.', 'tabela', '2.3.0', '2.3.0', 'added in V2.3.0', NULL),
  ('porporechop', 'por', 'porechop', 'Porechop', 'Um aplicativo de processamento de dados de sequenciamento projetado especificamente para o ajuste de adaptadores em dados da Oxford Nanopore Technologies.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porport', 'por', 'port', 'Porto ou ancoradouro', 'Um porto é qualquer corpo de água abrigado onde barcos ou navios podem atracar ou fundear. Um porto é uma instalação construída ao redor de um porto com instalações para carga e descarga dessas embarcações.', 'NA', '2.2.3', '2.2.3', 'added in v2.2.3', NULL),
  ('porpoSaSpecimenSet', 'por', 'poSaSpecimenSet', 'Conjunto de população ou amostra', 'Um conjunto de espécimes que inclui espécimes de população ou amostra.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porposCon', 'por', 'posCon', '#N/A', '#N/A', '#N/A', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpoSiSpecimenSet', 'por', 'poSiSpecimenSet', 'Conjunto de população ou local', 'Um conjunto de espécimes que inclui espécimes de população ou local.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porpoSpecimenSet', 'por', 'poSpecimenSet', 'Conjunto de espécimes de população', 'Um conjunto de espécimes que inclui apenas um espécime de população.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porpostgreSQL', 'por', 'postgreSQL', 'Licença PostgreSQL', 'O licenciamento da medida ou conjunto de dados é gerenciado pela Licença PostgreSQL.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpp', 'por', 'pp', 'Porcentagem positiva', 'Porcentagem positiva de medidas de amostra.', 'Pode ser usado para cotonetes Moore, etc.', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('porppm', 'por', 'ppm', 'partes por milhão', 'Partes por milhão.', 'NA', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('porppmv', 'por', 'ppmv', 'PMMoV-CP', 'Região do gene da proteína do capsídeo do vírus Pepper mild mottle.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('porpprt', 'por', 'pprt', 'Taxa de positividade percentual', 'Taxa percentual de positividade de testes realizados em um dia em uma determinada região.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('porpps', 'por', 'pps', 'Porcentagem de lodo primário', 'Porcentagem de sólidos totais, para lodo primário.', 'NA', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('porppt', 'por', 'ppt', 'partes por mil', 'Partes por mil.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpr', 'por', 'pr', 'Tabela de relacionamentos de protocolo Abreviação', 'O nome abreviado usado para referenciar a tabela que contém as informações organizacionais e detalhes (como a ordem) sobre um determinado protocolo, registrado como uma série de etapas do protocolo (etapasdoprotocolo).', 'tabela', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('porprec', 'por', 'prec', 'Precipitação (da solução)', 'A formação de um sólido a partir de uma substância dissolvida em uma solução, tipicamente induzida por reações químicas ou mudanças de temperatura/pH.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porprecip', 'por', 'precip', 'Precipitação - geral', 'Medida geral de precipitação, tipo não especificado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porprecipitation', 'por', 'precipitation', 'Classe de precipitação', 'Medidas e métodos relacionados à precipitação.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprecipitationUnitSet', 'por', 'precipitationUnitSet', 'Conjunto de unidades de precipitação', 'Conjunto de unidades para medições de precipitação.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porpreConcTemp', 'por', 'preConcTemp', 'Temperatura de armazenamento antes da concentração', 'A temperatura na qual uma amostra foi armazenada entre a coleta e a concentração.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpreConcTime', 'por', 'preConcTime', 'Tempo de armazenamento antes de Concentração', 'Período de tempo durante o qual uma amostra é armazenada entre a coleta e a concentração.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpredicted', 'por', 'predicted', 'Dados previstos', 'Dados previstos, dados gerados por modelos ou algoritmos de previsão, não obtidos diretamente de medições de amostra.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpredictiveModels', 'por', 'predictiveModels', 'Tipo de cálculo de modelagem preditiva', 'Uma abordagem estatística ou de aprendizado de máquina usada para estimar valores ou resultados futuros com base em padrões de dados históricos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpreExtractTemp', 'por', 'preExtractTemp', 'Temperatura de armazenamento antes da extração', 'A temperatura na qual uma amostra foi armazenada entre a concentração e a extração.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpreExtractTime', 'por', 'preExtractTime', 'Tempo de armazenamento antes da extração', 'Período de tempo durante o qual uma amostra é armazenada entre a concentração e a extração.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpreQC', 'por', 'preQC', 'pré-QC (da Meraculous)', 'Uma ferramenta de pipeline de CQ para sequenciamento de dados que avalia a qualidade dos dados antes da montagem, particularmente para genomas grandes.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpresampAct', 'por', 'presampAct', 'Atividade de pré-amostragem', 'Uma medida para registrar quaisquer atividades relevantes que ocorram a montante da fonte de amostragem. Por exemplo, registrar que o rio está coletando amostras de fluxos através de terras agrícolas, ou que a filtração e/ou sedimentação ocorreram na estação de tratamento de águas residuais antes da coleta da amostra.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpresampSet', 'por', 'presampSet', 'Conjunto de categorias de atividade de pré-amostragem', 'O conjunto de valores de entrada válidos para relatar a atividade pré-amostragem.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpreSampWeath', 'por', 'preSampWeath', 'Tempo de pré-amostragem', 'Condições climáticas que antecederam, mas não incluindo, o dia da amostragem.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpretreat', 'por', 'pretreat', 'Pré-tratamento', 'A amostra foi tratada quimicamente de alguma forma com a adição de estabilizantes ou outros?', 'O método de pré-tratamento pode ser descrito usando um método. Consulte ID do método.', '1.0.0', '2.0.0', 'NA', NULL),
  ('porprimClar', 'por', 'primClar', 'Clarificador primário', 'Um grande tanque de decantação que remove sólidos e materiais flutuantes das águas residuais antes do tratamento secundário.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porprimer', 'por', 'primer', 'Primer genético', 'ID do método usado para indicar o primer usado para um ensaio de PCR ou sequenciamento.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprimerSet', 'por', 'primerSet', 'Conjunto de primers genéticos', 'O conjunto de primers genéticos usados em ensaios de sequenciamento ou PCR.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprinseq', 'por', 'prinseq', 'PRINSEQ', 'Uma ferramenta de pipeline de CQ para sequenciamento de dados, visando avaliar e filtrar sequências com base em complexidade, pontuações de qualidade e conteúdo de GC.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porprinseqLite', 'por', 'prinseqLite', 'Prinseq-lite', 'Um aplicativo de processamento de dados de sequenciamento que filtra sequências com base em complexidade e remove leituras de baixa qualidade.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpriv', 'por', 'priv', 'Setor privado', 'A categoria de tipo de organização usada para grupos do setor privado ou sem fins lucrativos que não são abrangidos pela categoria acadêmica.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprivate', 'por', 'private', 'Dados privados - não para disseminação', 'A medida ou conjunto de dados são dados privados - não para divulgação.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpro', 'por', 'pro', 'Tabela de protocolos (Taquigrafia)', 'O nome abreviado usado para referenciar a tabela que contém informações resumidas e detalhes sobre um determinado protocolo.', 'tabela', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('porprocGrp', 'por', 'procGrp', 'Grupo de processamento', 'Um grupo de medidas/métodos relacionados ao processamento de amostras para análise.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprofil', 'por', 'profil', 'Levantamento ambiental ou perfilamento', 'O objetivo da amostragem/medida é registrar características e criar um perfil de um determinado ambiente.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porprogramDescr', 'por', 'programDescr', 'Tabelas de descrição do programa', 'Tabelas usadas para descrever programas de vigilância e testes.', 'As tabelas de descrição do programa registram metadados sobre organizações, locais e protocolos. As informações incluem nome, localização e outras informações de contato. Essas tabelas geralmente são preenchidas uma vez e atualizadas somente quando as informações de contato são alteradas.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprokka', 'por', 'prokka', 'Prokka (com integração de sorotipagem)', 'Prokka (com integração de sorotipagem) Embora seja principalmente uma ferramenta de anotação, as saídas do Prokka podem ser pareadas com bancos de dados para identificar sorotipos de certos patógenos bacterianos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porprokkaRoary', 'por', 'prokkaRoary', 'Prokka + Roary Pipeline (Nextflow)', 'Pipeline Prokka + Roary. Foco: Anotação genômica (Prokka) com MLST e integração de sorotipagem via Roary. Aplicações: Ampla compatibilidade com patógenos bacterianos. Características: Facilita a análise de MLST do genoma central e de genes acessórios.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porpromAuto', 'por', 'promAuto', 'Kit de tna automatizado Promega', 'Extração de ácido nucleico realizada com o kit de tna automatizado Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('porpromegaLVTNA', 'por', 'promegaLVTNA', 'Kit de captura de tna de grande volume para águas residuais Promega', 'Kit de captura de tna de grande volume para águas residuais Promega.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porpromHt', 'por', 'promHt', 'Kit de tna ht Promega', 'Extração de ácido nucleico realizada com o kit de tna ht Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('porpromManu', 'por', 'promManu', 'Kit de tna manual Promega', 'Extração de ácido nucleico realizada com o kit de tna manual Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('porpromWW', 'por', 'promWW', 'Kit de captura de TNA de grande volume para águas residuais Promega', 'Extração de ácido nucleico realizada com o kit de captura de tna de grande volume para águas residuais Promega.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, added from NWSS', NULL),
  ('porprop', 'por', 'prop', 'Proporção do total', 'Proporção como porcentagem do total.', 'NA', '1.0.0', '2.0.0', 'description wording.', NULL),
  ('porpropV', 'por', 'propV', 'Proporção da variante na amostra', 'Proporção de uma variante como porcentagem do total de variantes.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('porprotein', 'por', 'protein', 'Classe de proteínas', 'Medidas e métodos relacionados a proteínas.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolID', 'por', 'protocolID', 'ID do protocolo', 'Um identificador exclusivo para um determinado protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolIDContainer', 'por', 'protocolIDContainer', 'ID do contêiner do protocolo', 'Identificador exclusivo para o protocolo, as etapas e outros protocolos que o compõem.', 'O contêiner de ID do Protocolo é preenchido com um protocolID (partID = protocolID).', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolIDObj', 'por', 'protocolIDObj', 'Objeto do ID do protocolo', 'O objeto do relacionamento entre um protocolo e outro protocolo ou etapa, dentro de um determinado contêiner de ID de protocolo.', 'Preencha este campo usando o ID do Protocolo (partID = protocolID). Juntamente com `protocolIDSub` ou `stepIDSub` e `relationshipID`, o relacionamento do protocolo é definido como: [protocolIDSubject ou stepIDSubject] [relationshipID] [protocolIDObject ou stepIDObject]. Ex.: stepIDSubject precede protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolIDSub', 'por', 'protocolIDSub', 'Assunto do ID do protocolo', 'O assunto do relacionamento entre um protocolo e outro protocolo ou etapa, dentro de um determinado contêiner de ID de protocolo.', 'Preencha este campo usando o ID do Protocolo (partID = protocolID). Juntamente com `protocolIDObj` ou `stepIDObj` e `relationshipID`, a linha de `protocolRelationships` deve conter: [protocolIDSubject ou stepIDSubject] [relationshipID] [protocolIDObject ou stepIDObject]. Ex.: stepIDSubject precede protocolIDObject.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolRelationships', 'por', 'protocolRelationships', 'Tabela de relacionamentos do protocolo', 'A tabela que contém as informações organizacionais e detalhes (como a ordem) sobre um determinado protocolo, registrados como uma série de etapas do protocolo (protocolSteps).', 'Protocolos são um grupo de etapas de protocolo relacionadas. Por exemplo, uma etapa de protocolo pode descrever uma concentração de amostra, extração, inibição ou uma medição. Os protocolos podem incluir tanto methodID (um procedimento) quanto measureIDs (uma medida). Um exemplo de método é a centrifugação, onde a velocidade de rotação da centrifugação é descrita como uma medida.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolRelationshipsID', 'por', 'protocolRelationshipsID', 'ID sintético para o protocoloTabela de relacionamentos', 'Um ID exclusivo e autoincremental gerado para produzir um identificador exclusivo e uma chave primária para cada linha da tabela protocolRelationships.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porprotocolRelationshipsOrder', 'por', 'protocolRelationshipsOrder', 'Ordem das colunas da tabela de relacionamentos do protocolo', 'Especifica a ordem das colunas na tabela Organização do Protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolRelationshipsRequired', 'por', 'protocolRelationshipsRequired', 'Cabeçalhos obrigatórios da tabela de relacionamentos do protocolo', 'Especifica as colunas necessárias na tabela Organização do Protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolRelSet', 'por', 'protocolRelSet', 'Conjunto de relacionamentos do protocolo', 'definido para valores válidos de relationshipID na tabela protocolRelationships.', 'Usar somente para a tabela relationshipID de protocolRelationships.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocols', 'por', 'protocols', 'Tabela de protocolos', 'A tabela para protocolos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolsOrder', 'por', 'protocolsOrder', 'Ordem das colunas da tabela de protocolos', 'Especifica a ordem das colunas na tabela Protocolos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolsRequired', 'por', 'protocolsRequired', 'Cabeçalhos obrigatórios da tabela de protocolos', 'Especifica as colunas necessárias na tabela Protocolos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolSteps', 'por', 'protocolSteps', 'Tabela de etapas do protocolo', 'A tabela para coletar metadados sobre etapas individuais em um protocolo, processo metodológico ou ensaio.', 'NA', '1.0.0', '2.0.0', 'updated from assay method into 2 tables, restructured.', NULL),
  ('porprotocolStepsOrder', 'por', 'protocolStepsOrder', 'Ordem das colunas da tabela de etapas do protocolo', 'Especifica a ordem das colunas em uma tabela Etapas do Protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolStepsRequired', 'por', 'protocolStepsRequired', 'Cabeçalhos obrigatórios da tabela de etapas do protocolo', 'Especifica as colunas necessárias em uma tabela Etapas do Protocolo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolTableSet', 'por', 'protocolTableSet', 'Conjunto de tabelas do protocolo', 'Tabelas contendo informações sobre os métodos usados para coleta ou medição de amostras.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprotocolVersion', 'por', 'protocolVersion', 'Versão do protocolo', 'Especifica a versão de um conjunto de métodos.', 'Versão do conjunto de métodos. Recomenda-se o versionamento semântico.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porprovHA', 'por', 'provHA', 'Acesso ao prov ha', 'Se for "não", esses dados não estarão disponíveis para as autoridades de saúde provinciais. Se ausente, os dados estarão disponíveis para as autoridades de saúde provinciais.', 'NA', '1.0.0', '2.0.0', 'depreciated, sharing moved to sharing schema.', NULL),
