  ('portemperature', 'por', 'temperature', 'Classe de temperatura', 'Medidas e métodos relacionados a temperaturas.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portemperatureUnitSet', 'por', 'temperatureUnitSet', 'Conjunto de unidades de temperatura', 'Conjunto de unidades para medições de temperatura.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portemplateSheetSet', 'por', 'templateSheetSet', 'Conjunto de folhas de modelo', 'Planilhas no modelo genérico completo de vigilância do ODM (todas as tabelas).', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portempSet', 'por', 'tempSet', 'Conjunto de modelo', 'O conjunto organizador para modelos.', 'NA', '2.2.0', '2.2.0', 'Added in V 2.2.0', NULL),
  ('portempType', 'por', 'tempType', 'Tipo de modelo de ácido nucleico', 'Especifica se uma PCR ou sequenciamento utilizou RNA ou DNA como modelo para a reação.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portempVol', 'por', 'tempVol', 'Volume do modelo de ácido nucleico', 'O volume de DNA ou RNA modelo utilizado para PCR.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porterminal', 'por', 'terminal', 'Terminal do aeroporto', 'Tipo de categoria de galpão de amostra do terminal do aeroporto', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portesDate', 'por', 'tesDate', 'Data do teste', 'Data em que o teste de COVID-19 foi realizado.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('portest', 'por', 'test', 'Número de testes realizados', 'Número de testes realizados.', 'NA', '1.0.0', '2.0.0', 'now a unit for any group or biologic infection', NULL),
  ('portesting', 'por', 'testing', 'Teste de protocolo', 'Uma medida ou amostra coletada para testar um novo método. Essas medidas são normalmente usadas para uso interno em laboratórios e não são reportadas a parceiros externos.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portetAMRGrp', 'por', 'tetAMRGrp', 'Grupo de resistência antimicrobiana à tetraciclina', 'O grupo para medidas e métodos relativos à resistência antimicrobiana relacionada à tetraciclina.', 'NA', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('portetW', 'por', 'tetW', 'Alvo genético de resistência à tetraciclina TetW', 'O gene-alvo de resistência antimicrobiana à tetraciclina tetW.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porthermCyc', 'por', 'thermCyc', 'Ciclistas térmicos', 'Um instrumento termociclador, usado para realizar reações com temperatura controlada para PCR.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porthermMag', 'por', 'thermMag', 'Kit de isolamento de ácido nucleico Thermo Magmax Microbiome Ultra', 'Extração de ácido nucleico realizada com o kit de isolamento de ácido nucleico Thermo Magmax Microbiome Ultra.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porthermMagmax', 'por', 'thermMagmax', 'Kit de isolamento de ácido nucleico viral/patógeno Thermo Magmax', 'Kit de isolamento de ácido nucleico viral/patógeno Thermo Magmax', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porthreatDes', 'por', 'threatDes', 'Designação da ameaça', 'Um tipo de ação de saúde pública em que um nível de ameaça é determinado e comunicado pelas autoridades.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porthreatDesSet', 'por', 'threatDesSet', 'Conjunto de valores da designação da ameaça', 'Um conjunto de categorias válidas para o campo de ação de saúde pública, onde o tipo de ação é "designação de ameaça".', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porthreatTarget', 'por', 'threatTarget', 'Ameaça à saúde pública visada pela ação', 'O patógeno ou variante para o qual a designação ou ação está sendo tomada.', 'Preenchida por um tipo de peça ''measurement''.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porthruPLEX', 'por', 'thruPLEX', 'Kit ThruPLEX DNA-seq', 'Kit ThruPLEX DNA-seq da Takara Bio. Um kit de preparação de biblioteca de baixo consumo com protocolo rápido de três etapas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portHub', 'por', 'tHub', 'Centro de transporte - Geral', 'Um centro de transporte não especificado de outra forma. Ou seja, um local onde passageiros e cargas são trocados entre veículos e/ou entre modos de transporte.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portimeClass', 'por', 'timeClass', 'Horário classe', 'Medidas e métodos relacionados ao tempo.', 'NA', '2.0.0', '3.0.0', 'partID changed from "time" to "timeClass"', NULL),
  ('portimePr', 'por', 'timePr', 'Amostra proporcional ao tempo', 'Uma amostra composta proporcional ao tempo, geralmente coletada por um amostrador automático.', 'Use collectionPeriod para descrever quantas horas a amostra foi coletada.', '1.0.0', '2.0.0', 'Removed time period. Use collection period (collectPer) = 24 for 24hr sample', NULL),
  ('portimeStand', 'por', 'timeStand', 'Tempo padronizado', 'Este tratamento de dados padroniza o valor medido em relação ao tempo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portimeUnitSet', 'por', 'timeUnitSet', 'Conjunto de unidades de tempo', 'A unidade definida para medidas de tempo.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portkn', 'por', 'tkn', 'Nitrogênio Kjeldahl total', 'Uma medida do Nitrogênio Kjeldahl Total; ou seja, a soma do nitrogênio ligado em substâncias orgânicas, nitrogênio na amônia (NH3-N) e na amônia (NH4+-N) na análise química do solo, água ou águas residuais.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portld', 'por', 'tld', 'Domínio de nível superior do código do país', 'O domínio de nível superior da internet geralmente usado ou reservado para um país, estado soberano ou território dependente identificado com um código de país.', 'Pré-programado em tabelas de dicionário, não editável pelos usuários.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('portn', 'por', 'tn', 'Nitrogênio total', 'Concentração total de nitrogênio, como N.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('portophat', 'por', 'tophat', 'TopHat', 'TopHat. Um mapeador de leitura de uso geral. Um alinhador de RNA-seq mais antigo, com reconhecimento de splicing. Substituído pelo HISAT2 na maioria dos fluxos de trabalho. Ideal para: Estudos históricos de RNA-seq.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portotal', 'por', 'total', 'Quantidade total ou contagem - a soma', 'O número total ou contagem final de casos, ou outra métrica definida.', 'Agregação para uma medida de população ou doença para explicar os efeitos clínicos em nível populacional.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portp24s', 'por', 'tp24s', 'Amostra de 24 horas proporcional ao tempo', 'Uma amostra composta de 24 horas proporcional ao tempo, geralmente coletada por um amostrador automático.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('portPallidum', 'por', 'tPallidum', 'Treponema pallidum', 'Treponema pallidum', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portr', 'por', 'tr', 'Tabela de consulta de tradução - Taquigrafia', 'Nome abreviado usado para referenciar a tabela de consulta para traduções da descrição, rótulo e instruções de todas as peças.', 'tabela', '2.2.2', '2.2.2', 'added in V 2.2.2', NULL),
  ('portradSero', 'por', 'tradSero', 'Métodos tradicionais de sorotipagem', 'Métodos tradicionais de sorotipagem usados para sorotipagem.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portrain', 'por', 'train', 'Trem', 'Uma série de vagões ferroviários movidos como uma unidade por uma locomotiva ou por motores integrais.', 'NA', '2.2.3', '2.2.3', 'added in v2.2.3', NULL),
  ('portranslationID', 'por', 'translationID', 'ID sintético para a tabela de traduções', 'Um ID único e autoincremental gerado para produzir um identificador único e uma chave primária para cada linha da tabela de traduções.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portranslations', 'por', 'translations', 'Tabela de consulta de tradução', 'Tabela de consulta para traduções da descrição, rótulo e instruções de todas as peças.', 'O idioma padrão, caso uma tradução não seja especificada, é o inglês.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portranslationsOrder', 'por', 'translationsOrder', 'Ordem das colunas da tabela de tradução', 'Especifica a ordem das colunas na tabela de traduções.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portranslationsRequired', 'por', 'translationsRequired', 'Cabeçalhos obrigatórios da tabela de tradução', 'Cabeçalhos obrigatórios na tabela de traduções.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portransp', 'por', 'transp', 'Veículo de transporte - geral', 'Um veículo, ou seja, uma máquina móvel, que transporta pessoas ou carga, de um tipo não especificado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portrap', 'por', 'trap', 'Amostragem passiva (armadilha)', 'Um amostrador composto que coleta passivamente uma amostra sem o uso de eletricidade ou bateria.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portravBa', 'por', 'travBa', 'Proibição de viagem', 'Uma restrição que proíbe viagens de ou para locais específicos.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portravelSurv', 'por', 'travelSurv', 'Vigilância do hub de viagens - geral', 'Uma estratégia de vigilância na qual as águas residuais produzidas em centros de transporte ou veículos de transporte são monitoradas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portravWa', 'por', 'travWa', 'Aviso de viagem', 'Um aviso desaconselhando viagens a determinadas áreas devido a riscos à saúde.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portreat', 'por', 'treat', 'Tratado', 'Uma qualidade que denota um estado alterado de um item resultante de intervenções ou processos intencionais.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portreatmentID', 'por', 'treatmentID', 'ID do tratamento', 'Um identificador único para um único cálculo/tratamento de dados, um identificador único para tratamento de dados.', 'Podem ser agrupados em um pipeline, que é então vinculado a uma medida. Isso é feito fazendo com que todos os tratamentos relacionados compartilhem o mesmo pipelineID e especificando a ordem dos tratamentos no pipeline usando o campo de ordem.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portreeTime', 'por', 'treeTime', 'Software TreeTime', 'Uma ferramenta de software de análise de linhagem ou clado para análise filodinâmica, frequentemente para datação por relógio molecular e atribuição de clado.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portreponemaGrp', 'por', 'treponemaGrp', 'Grupo Treponema', 'Um grupo de medidas/métodos relacionados à bactéria Treponema.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portrichomonasGrp', 'por', 'trichomonasGrp', 'Grupo Trichomonas', 'Um grupo de medidas/métodos relacionados à bactéria Trichomonas.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portrimGalore', 'por', 'trimGalore', 'TrimGalore!', 'Uma ferramenta de pipeline de CQ para sequenciamento de dados que integra Cutadapt e FastQC para avaliar a qualidade da sequência e remover adaptadores em uma única etapa.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portrimmomatic', 'por', 'trimmomatic', 'Trimmomatic', 'Um aplicativo de processamento de dados de sequenciamento que remove adaptadores e bases de baixa qualidade das leituras de sequenciamento Illumina.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portrinity', 'por', 'trinity', 'Trinity', 'Um software de sequenciamento que é um montador projetado especificamente para dados de RNA-sequenciamento, criando conjuntos de transcriptoma.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portrisEDTA', 'por', 'trisEDTA', 'Tampão TE (Tris-EDTA)', 'Uma solução/meio tampão que preserva a estabilidade do DNA em amostras ambientais.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portriturator', 'por', 'triturator', 'Triturador de Águas Residuais', 'O local onde os veículos de transporte de águas residuais descarregam as águas residuais.', 'NA', '2.2.3', '2.2.3', 'added in v 2.2.3', NULL),
  ('portrizol', 'por', 'trizol', 'trizol, esferas magnéticas Zymo com Zymo Clean e concentrador', 'Extração de ácido nucleico realizada com o método trizol, esferas de zymo mag com zymo clean e concentrador.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portrizolEtOH', 'por', 'trizolEtOH', 'trizol, batimento de esferas de granada, precipitação com álcool', 'trizol, batimento de esferas de granada, precipitação com álcool', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portrizolRNA', 'por', 'trizolRNA', 'Kit de purificação de trizol e RNA', 'Kit de purificação de trizol e RNA', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portrStat', 'por', 'trStat', 'Estação de trem', 'Um local em uma linha férrea onde os trens param regularmente para que os passageiros possam embarcar ou desembarcar.', 'NA', '2.2.3', '2.2.3', 'added in v2.2.3', NULL),
  ('portruSeqDNA', 'por', 'truSeqDNA', 'Kit de preparação de biblioteca TruSeq DNA PCR-Free', 'Kit de Preparação de Biblioteca TruSeq DNA PCR-Free da Illumina. Um kit de preparação de biblioteca de alta qualidade sem amplificação por PCR, reduzindo o viés.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('ports', 'por', 'ts', 'Concentração de sólidos totais', 'Concentração de sólidos totais', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('portsb', 'por', 'tsb', 'Caldo de soja tríptico (TSB)', 'Caldo de Soja Tríptico (TSB) - Um meio rico em nutrientes para a sobrevivência bacteriana, às vezes usado para armazenamento de curto prazo.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('portss', 'por', 'tss', 'Sólidos suspensos totais', 'Sólidos Suspensos Totais', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('portssConc', 'por', 'tssConc', 'Concentração de sólidos suspensos totais', 'Concentração de sólidos suspensos totais da água residual.', 'NA', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('portuberculosisGrp', 'por', 'tuberculosisGrp', 'Grupo Tuberculose', 'Um grupo de medidas/métodos relacionados à tuberculose.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portularemiaGrp', 'por', 'tularemiaGrp', 'Grupo Francisella tularensis (tularemia)', 'Um grupo de medidas/métodos relacionados à Francisella tularensis.', 'Usado para descrever as informações do organismo para medidas gerais.', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porturb', 'por', 'turb', 'Turbidez', 'Uma medida para a turbidez da água, ou de uma amostra líquida, quantificando a claridade ou opacidade relativa de um líquido. Altamente indicativo da qualidade da água.', 'NA', '1.0.0', '2.0.0', 'github issue #122', NULL),
  ('porturbidity', 'por', 'turbidity', 'Classe de turbidez', 'Medidas e métodos relacionados à turbidez da água e das águas residuais.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porturbidityUnitSet', 'por', 'turbidityUnitSet', 'Conjunto de unidades de turbidez', 'Conjunto de unidades para medições de turbidez.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portVaginalis', 'por', 'tVaginalis', 'Trichomonas vaginalis', 'Trichomonas vaginalis', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('portWeighE', 'por', 'tWeighE', 'Peso do tubo vazio', 'O peso do tubo usado para análise enquanto vazio.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portWeighF', 'por', 'tWeighF', 'Peso do tubo cheio', 'O peso do tubo usado para análise enquanto cheio de analito.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('portyOtDep', 'por', 'tyOtDep', 'Tipo outro depreciado', 'Descrição para outro tipo de amostra não listado em', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('portyOtDep2', 'por', 'tyOtDep2', 'Tipo outro depreciado2', 'Descrição do local quando o local não estiver listado. Consulte SiteType.', 'NA', '1.0.0', '2.0.0', 'depreciated', NULL),
  ('poruCampus', 'por', 'uCampus', 'Campus universitário', 'Campus universitário ou universitário - abrangendo um campus inteiro ou parte de um campus.', 'Veja também "Domínio do Ensino Superior".', '1.1.0', '2.0.0', 'added in version 1.1', NULL),
  ('poruGene', 'por', 'uGene', 'Ugene', 'Software de sequenciamento que oferece recursos de alinhamento e geração de sequências de consenso.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porugG', 'por', 'ugG', 'Microgramas por grama', 'Microgramas por grama', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porugL', 'por', 'ugL', 'Microgramas por litro', 'Microgramas por litro', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porugmg', 'por', 'ugmg', 'Microgramas por miligrama', 'Unidade de concentração de microgramas por miligrama.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poruL', 'por', 'uL', 'Microlitros', 'A unidade de microlitros.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porultraCentInst', 'por', 'ultraCentInst', 'Ultracentrífugas', 'Instrumentos de ultracentrífuga; usados para separação de partículas em escala fina.', 'Centrífugas padrão são uma opção de tipo de instrumento separada.', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porumhocm', 'por', 'umhocm', 'Micromho por centímetro', 'Micromho por centímetro (μmho/cm)', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porumiTag', 'por', 'umiTag', 'Marcação com Identificador Molecular Único (UMI)', 'Um método de desduplicação que adiciona marcadores exclusivos a fragmentos individuais de DNA, permitindo a identificação e a remoção de leituras duplicadas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porumiTools', 'por', 'umiTools', 'Ferramentas UMI', 'Um método de desduplicação dedicado à desduplicação de leituras usando identificadores moleculares exclusivos, especialmente eficaz em fluxos de trabalho de RNA-seq e de célula única.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porundisc', 'por', 'undisc', 'Não divulgado', 'Um valor foi registrado, porém não foi incluído no conjunto de dados.', 'Indicador de valor ausente para dados que não foram compartilhados ou divulgados com terceiros.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porunicycler', 'por', 'unicycler', 'Unicycler', 'Um software de sequenciamento que é um montador híbrido para genomas bacterianos, combinando leituras curtas e longas.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porunique', 'por', 'unique', 'Amostra única', 'Uma amostra única, não duplicada.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0, GitHub issue #94', NULL),
  ('porunit', 'por', 'unit', 'Unidade', 'As unidades de uma medição.', 'Diferentes unidades usadas para descrever valores de medição. As unidades são combinadas em UnitSetIDs. Solicite novas unidades criando uma issue no repositório do ODM.', '1.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porunitInput', 'por', 'unitInput', 'Entrada da unidade (tabela ampla)', 'O partID para a unidade que está sendo usada em um nome amplo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porunitless', 'por', 'unitless', 'Medida sem unidade', 'Uma unidade para medidas sem unidade, como pH.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL);
INSERT INTO `translations` (`translationID`, `lang`, `partID`, `partLabel`, `partDesc`, `partInstr`, `firstReleased`, `lastUpdated`, `changes`, `notes`) VALUES
  ('porunitlessUnitSet', 'por', 'unitlessUnitSet', 'Conjunto de unidades sem unidade', 'Conjunto de unidades para medições que não possuem unidades.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porunitName', 'por', 'unitName', 'Nome da unidade (tabela ampla tabela)', 'A unidade referenciada para o nome amplo.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('porunits', 'por', 'units', 'Unidades', 'A unidade da medição.', 'Toda medição deve ter uma unidade. Ou seja, `unidades` é um campo obrigatório sempre que uma medição é registrada.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porunitSet', 'por', 'unitSet', 'Conjunto de unidades', 'Uma identificação de um conjunto de unidades que pode ser usado para uma medida ou método.', 'NA', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porunitSets', 'por', 'unitSets', 'Conjuntos de unidades', 'Conjuntos de unidades. Contém unidades que estão associadas a tipos de partes, como medidas.', 'Conjuntos são listas de valores de entrada. Cada valor de entrada dentro de um conjunto é uma parte (possui um partID) que pode ser reutilizada entre conjuntos. Por exemplo, um conjunto A pode conter os valores ''sim'' e ''não''; e o conjunto B pode conter os valores ''sim'', ''não'' e ''talvez''. PartTypes com conjuntos incluem agregações, compartimentos, ausências, sinalizadores de qualidade, espécimes e unidades. Medidas com categorias e DataTypes têm seus próprios conjuntos específicos (catSetID) porque seus valores de entrada são únicos e não são reutilizados.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('porunkn', 'por', 'unkn', 'Amostra desconhecida', 'Denota um tipo de réplica de amostra desconhecido.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porunlicense', 'por', 'unlicense', 'A Licença Não Autorizada', 'O licenciamento para a medida ou conjunto de dados é gerenciado sob a licença Unlicense.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
  ('poruntracent', 'por', 'untracent', 'Ultracentrifugação', 'Ultracentrifugação', 'Normalmente, deve ser vinculado a um limite inferior e alguma indicação da dispersão dos dados (por exemplo, desvio padrão) e uma medida de média/mediana.', '2.0.0', '2.0.0', 'added in V2.0.0', NULL),
  ('poruntreat', 'por', 'untreat', 'Sem tratamento', 'Uma qualidade que denota a ausência de intervenção ou processos intencionais em um item.', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porupperCI95', 'por', 'upperCI95', 'Limite superior de um intervalo de confiança de 95%', 'Especifica o limite superior de um intervalo de confiança de 95%.', 'Uma categoria abrangente para locais de amostragem de águas residuais a montante, incluindo grandes tubulações de esgoto e estações de bombeamento.', '1.0.0', '2.0.0', 'description wording, structure', NULL),
  ('porupstream', 'por', 'upstream', 'Locais a montante', 'Um tipo geral de local para locais de amostragem de águas residuais a montante.', 'NA', '1.1.0', '2.0.0', 'description wording.', NULL),
  ('porurban', 'por', 'urban', 'Urbano', 'Tipo de área urbana povoada', 'NA', '3.0.0', '3.0.0', 'added in V3.0.0', NULL),
  ('porureaplasma', 'por', 'ureaplasma', 'Ureaplasma', 'Ureaplasma', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
