  ('porutc', 'por', 'utc', 'Fuso horário universal coordenado (UTC)', 'UTC – Fuso horário.', 'Pré-programado em tabelas de dicionário, não editável pelos usuários.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('porutcDST', 'por', 'utcDST', 'Fuso horário universal coordenado (UTC) no horário de verão', 'Fuso horário durante o Horário de Verão.', 'Pré-programado em tabelas de dicionário, não editável pelos usuários.', '2.1.0', '2.1.0', 'added in V2.1.0', NULL),
  ('porutilities', 'por', 'utilities', 'Setor ou organização de serviços públicos', 'Descreve organizações que gerenciam ou fornecem serviços públicos, como água, gás, aquecimento, etc.', 'NA', '2.2.0', '2.2.0', 'added in V2.2.0', NULL),
